    function sanitizeCurrencyCode(currency) {
        const code = String(currency || '').trim().toUpperCase();
        const reserved = new Set(['TRUE', 'FALSE', 'AUTO', 'MANUAL', 'CRYPTO', 'FIAT', 'CURRENCY', 'WALLET']);
        return /^[A-Z0-9]{2,12}$/.test(code) && !reserved.has(code) ? code : null;
    }

    function ensureCurrencyRegistered(currency) {
        const code = sanitizeCurrencyCode(currency);
        return code && SUPPORTED_CURRENCY_SET.has(code) ? code : null;
    }

    function discoverStakeCurrencies(root = document) {
        if (!root || root.nodeType !== 1 && root.nodeType !== 9) return [];
        const selector = NATIVE_CURRENCY_CANDIDATE_SELECTOR;
        const elements = [];
        if (root.nodeType === 1 && root.matches?.(selector)) elements.push(root);
        root.querySelectorAll?.(selector).forEach(element => elements.push(element));

        const discovered = [];
        for (const element of elements) {
            if (element.closest?.('#balance-ui')) continue;
            const testId = element.getAttribute('data-testid') || '';
            const match = testId.match(/^coin-toggle-currency-([a-z0-9]{2,12})$/i);
            const raw = match?.[1]
                || element.getAttribute('data-currency-code')
                || element.getAttribute('data-currency');
            const code = sanitizeCurrencyCode(raw);
            if (!code) continue;
            if (SUPPORTED_CURRENCY_SET.has(code)) discovered.push(code);
        }
        return [...new Set(discovered)];
    }

    function normalizeCurrency(currency) {
        const code = String(currency || DEFAULT_CURRENCY).trim().toUpperCase();
        return SUPPORTED_CURRENCY_SET.has(code) ? code : DEFAULT_CURRENCY;
    }

    function getRawCurrencyCodeFromElement(element) {
        if (!element || element.nodeType !== 1) return null;
        const choice = element.matches?.('button, [role="button"], [role="option"]')
            ? element
            : element.closest?.('button, [role="button"], [role="option"]');
        if (!choice) return null;

        const testId = choice.getAttribute('data-testid') || '';
        const testIdMatch = testId.match(/^coin-toggle-currency-([a-z0-9]{2,12})$/i);
        const explicit = testIdMatch?.[1]
            || choice.getAttribute('data-currency-code')
            || choice.getAttribute('data-currency')
            || choice.querySelector('svg[data-ds-icon]')?.getAttribute('data-ds-icon')
            || choice.querySelector('span[title]')?.getAttribute('title');
        const explicitCode = sanitizeCurrencyCode(explicit);
        if (explicitCode) return explicitCode;

        const label = `${choice.getAttribute('aria-label') || ''} ${choice.textContent || ''}`.toUpperCase();
        const tokens = label.match(/\b[A-Z][A-Z0-9]{1,11}\b/g) || [];
        return tokens.map(sanitizeCurrencyCode).find(Boolean) || null;
    }

    function isStakeNativeWalletSurface(element) {
        if (!element || element.nodeType !== 1 || element.closest?.('#balance-ui')) return false;
        const surface = element.closest?.(
            '[role="dialog"], [role="listbox"], [role="menu"], [data-testid*="wallet" i], [data-testid*="currency" i]'
        );
        if (!surface || surface.closest?.('#balance-ui')) return false;
        if (surface.matches?.('[role="listbox"], [role="menu"]')) return true;
        if (surface.querySelector?.(NATIVE_CURRENCY_CANDIDATE_SELECTOR)) return true;
        const label = `${surface.getAttribute?.('aria-label') || ''} ${surface.getAttribute?.('data-testid') || ''} ${surface.textContent || ''}`;
        return /wallet|currency|display\s+crypto\s+in\s+fiat/i.test(label);
    }

    function filterUnsupportedStakeCurrencies(root = document) {
        if (!root || root.nodeType !== 1 && root.nodeType !== 9) return;
        const candidates = new Set();
        if (root.nodeType === 1 && root.matches?.(NATIVE_CURRENCY_CANDIDATE_SELECTOR)) candidates.add(root);
        root.querySelectorAll?.(NATIVE_CURRENCY_CANDIDATE_SELECTOR).forEach(element => candidates.add(element));
        if (root.nodeType === 1 && root.matches?.('[data-athr-unsupported-currency]')) candidates.add(root);
        root.querySelectorAll?.('[data-athr-unsupported-currency]').forEach(element => candidates.add(element));

        candidates.forEach(element => {
            const choice = element.matches?.('button, [role="option"]')
                ? element
                : element.closest?.('button, [role="option"]');
            if (!choice || choice.closest?.('#balance-ui')) return;
            // v5.2 never filters or rebuilds Stake's native wallet. Restore any
            // node hidden by an older ATHR build and let Stake own availability,
            // icons, focus, search, scrolling and row balances.
            if (choice.hasAttribute('data-athr-unsupported-currency')) {
                const previousDisplay = choice.getAttribute('data-athr-previous-display') || '';
                choice.hidden = false;
                choice.removeAttribute('aria-hidden');
                choice.removeAttribute('data-athr-unsupported-currency');
                choice.removeAttribute('data-athr-previous-display');
                choice.style.removeProperty('display');
                if (previousDisplay) choice.style.display = previousDisplay;
            }
        });
    }

    function renderCurrencyOptions(selectedCurrency) {
        const selected = normalizeCurrency(selectedCurrency);
        return SUPPORTED_CURRENCY_CODES
            .map(code => `<option value="${code}" ${code === selected ? 'selected' : ''}>${code} \u2014 ${CRYPTO_CURRENCIES[code].name}</option>`)
            .join('');
    }

    function formatWalletChipBalance(amount, currency = selectedBalanceCurrency) {
        const usdValue = Math.max(0, Number(amount) || 0);
        const mode = getDisplayAmountMode();
        if (mode === 'CRYPTO') return formatCryptoDisplayAmount(usdValue, currency);
        const localRate = mode === 'LOCAL' ? getEffectiveFiatRate() : 1;
        if (mode === 'LOCAL' && !(localRate > 0)) return `${getLocalCurrencySymbol()}\u2026`;
        const value = mode === 'LOCAL' ? usdValue * localRate : usdValue;
        const symbol = mode === 'LOCAL' ? getLocalCurrencySymbol() : '$';
        if (value >= 1000000000) return `${symbol}${(value / 1000000000).toFixed(value >= 10000000000 ? 0 : 1)}B`;
        if (value >= 1000000) return `${symbol}${(value / 1000000).toFixed(value >= 10000000 ? 0 : 1)}M`;
        if (value >= 1000) return `${symbol}${(value / 1000).toFixed(value >= 10000 ? 0 : 1)}K`;
        return `${symbol}${value.toLocaleString('en-US', { maximumFractionDigits: value < 10 ? 2 : 0 })}`;
    }

    function renderCurrencyDeckHTML() {
        return SUPPORTED_CURRENCY_CODES.map(code => {
            const meta = CRYPTO_CURRENCIES[code];
            const balance = getCryptoBalance(code);
            const selectedClass = code === selectedBalanceCurrency ? ' is-selected' : '';
            const activeClass = code === activeGameCurrency ? ' is-active' : '';
            return `
                <button type="button" class="athr-coin-btn${selectedClass}${activeClass}" data-athr-wallet="${code}" title="${meta.name}: ${formatBalance(balance, code)}" aria-label="Use ${meta.name}; balance ${formatBalance(balance, code)}">
                    ${getCurrencyIconSVG(code, 27, 'athr-coin-logo')}
                    <span class="athr-coin-code">${code}</span>
                    <span class="athr-coin-usd">${formatWalletChipBalance(balance, code)}</span>
                </button>
            `;
        }).join('');
    }

    function refreshCurrencyControls() {
        const codes = SUPPORTED_CURRENCY_CODES;
        const deck = document.getElementById('athr-coin-grid');
        if (deck && deck.dataset.athrCatalog !== codes.join('|')) {
            deck.innerHTML = renderCurrencyDeckHTML();
            deck.dataset.athrCatalog = codes.join('|');
        }

        const count = document.getElementById('athr-wallet-count');
        if (count) count.textContent = `${codes.length} balances`;

        ['athr-currency-select', 'withdrawal-currency-select', 'deposit-currency-select'].forEach(id => {
            const select = document.getElementById(id);
            if (!select || select.options.length === codes.length) return;
            const previous = normalizeCurrency(select.value || (id === 'athr-currency-select' ? activeGameCurrency : DEFAULT_CURRENCY));
            select.innerHTML = renderCurrencyOptions(previous);
            select.value = previous;
        });
    }

    function getRenderedCurrencySVG(currency) {
        const code = ensureCurrencyRegistered(currency) || DEFAULT_CURRENCY;
        const source = CRYPTO_CURRENCIES[code].svg;
        if (code !== 'SOL' || !source.includes('SOL__a')) return source;
        currencyIconSequence += 1;
        return source.replaceAll('SOL__a', `SOL__a_${currencyIconSequence}`);
    }

    function getCurrencyIconSVG(currency, size = 24, className = '') {
        const code = ensureCurrencyRegistered(currency) || DEFAULT_CURRENCY;
        return `<svg data-ds-icon="${code}" width="${size}" height="${size}" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" fill="none" class="${className}" aria-hidden="true">${getRenderedCurrencySVG(code)}</svg>`;
    }

    function applyCurrencyIcon(svg, currency) {
        if (!svg || svg.nodeType !== 1) return;
        const code = ensureCurrencyRegistered(currency);
        if (!code) return;
        const meta = CRYPTO_CURRENCIES[code];
        if (svg.getAttribute('data-athr-icon-rendered') === code &&
            svg.getAttribute('data-ds-icon') === code) {
            return;
        }

        svg.setAttribute('data-ds-icon', code);
        svg.setAttribute('data-athr-icon-rendered', code);
        svg.setAttribute('viewBox', '0 0 24 24');
        svg.innerHTML = getRenderedCurrencySVG(code);
    }

    function getTransactionExplorerUrl(currency, txHash) {
        const code = normalizeCurrency(currency);
        return CRYPTO_CURRENCIES[code].explorer + encodeURIComponent(String(txHash || ''));
    }

    function applyCurrencyToHistoryRow(row, currency, txHash) {
        if (!row) return;
        const code = normalizeCurrency(currency);
        const currencySpan = row.querySelector('td:first-child span[title]');
        if (currencySpan) {
            currencySpan.setAttribute('title', code.toLowerCase());
            currencySpan.setAttribute('aria-label', `${CRYPTO_CURRENCIES[code].name} (${code})`);
            const svg = currencySpan.querySelector('svg');
            if (svg) applyCurrencyIcon(svg, code);
        }

        Array.from(row.classList)
            .filter(className => className.endsWith('-withdrawal'))
            .forEach(className => row.classList.remove(className));
        row.classList.add(`${code.toLowerCase()}-withdrawal`);
        row.setAttribute('data-crypto-currency', code);

        const transactionLink = row.querySelector('td:nth-child(4) a');
        if (transactionLink) {
            transactionLink.href = getTransactionExplorerUrl(code, txHash);
        }
    }

    function isFrozenCurrencyScope(element) {
        return !!element?.closest?.(
            'tr[data-withdrawal-index], tr[data-deposit-index], tr[data-bet-index], [data-fake-bet-modal="true"], [data-athr-currency-snapshot="true"]'
        );
    }

    function applyActiveCurrencyInSubtree(root, currency = activeGameCurrency) {
        if (!root || root.nodeType !== 1) return;
        if (root.closest?.('tr[data-withdrawal-index], tr[data-deposit-index], tr[data-bet-index], [data-fake-bet-modal="true"]') ||
            root.matches?.('tr[data-withdrawal-index], tr[data-deposit-index], tr[data-bet-index], [data-fake-bet-modal="true"]')) return;
        if (root.closest?.('#balance-ui, #athr-wallet-balances-popover') || root.matches?.('#balance-ui, #athr-wallet-balances-popover')) return;
        if (isStakeNativeWalletSurface(root)) return;

        const code = normalizeCurrency(currency);
        const supportedCodes = Object.keys(CRYPTO_CURRENCIES);
        const titledSelector = supportedCodes.map(item => `span[title="${item.toLowerCase()}"]`).join(',');
        const titled = root.matches(titledSelector) ? [root] : Array.from(root.querySelectorAll(titledSelector));
        for (const el of titled) {
            if (!isFrozenCurrencyScope(el)) {
                el.setAttribute('title', code.toLowerCase());
            }
        }

        const svgSelector = supportedCodes.map(item => `svg[data-ds-icon="${item}"]`).join(',');
        const svgs = root.matches(svgSelector) ? [root] : Array.from(root.querySelectorAll(svgSelector));
        for (const svg of svgs) {
            if (!isFrozenCurrencyScope(svg)) {
                applyCurrencyIcon(svg, code);
            }
        }

        const textSpans = root.matches('span[data-ds-text="true"]') ? [root] : Array.from(root.querySelectorAll('span[data-ds-text="true"]'));
        for (const span of textSpans) {
            if (isFrozenCurrencyScope(span)) continue;
            const t = span.textContent || '';
            const currencyOnly = t.trim().toUpperCase();
            if (supportedCodes.includes(currencyOnly) && currencyOnly !== code) {
                span.textContent = t.replace(currencyOnly, code);
            }
        }
    }

    function forceBTCInSubtree(root) {
        applyActiveCurrencyInSubtree(root, activeGameCurrency);
    }

    async function refreshCryptoRates() {
        try {
            const ids = Object.values(CRYPTO_CURRENCIES).map(meta => meta.coingeckoId).filter(Boolean).join(',');
            if (!ids) return;
            const data = await requestJSON(`https://api.coingecko.com/api/v3/simple/price?ids=${encodeURIComponent(ids)}&vs_currencies=usd`, {
                method: 'GET',
                timeout: 8000
            });
            for (const [code, meta] of Object.entries(CRYPTO_CURRENCIES)) {
                const next = meta.coingeckoId && data && data[meta.coingeckoId] && typeof data[meta.coingeckoId].usd === 'number'
                    ? data[meta.coingeckoId].usd
                    : null;
                if (next && Number.isFinite(next) && next > 0) {
                    CRYPTO_RATES[code] = next;
                }
            }
            updateBalanceUI();
        } catch (e) { }
    }

    async function refreshBTCRate() {
        return refreshCryptoRates();
    }

    function getStats() {
        const saved = localStorage.getItem(STATS_KEY);
        if (!saved) return {profit:0, wagered:0, wins:0, losses:0, profitHistory:[0]};
        try {
            const p = JSON.parse(saved);
            if (!Array.isArray(p.profitHistory)) p.profitHistory = [0];
            return {...{profit:0, wagered:0, wins:0, losses:0, profitHistory:[0]}, ...p};
        } catch(e) {
            return {profit:0, wagered:0, wins:0, losses:0, profitHistory:[0]};
        }
    }

    function saveStats() {
        localStorage.setItem(STATS_KEY, JSON.stringify(fakeStats));
    }

    function resetStats() {
        fakeStats = {profit:0, wagered:0, wins:0, losses:0, profitHistory:[0]};
        saveStats();
    }

    fakeStats = getStats();

    function drawGraph(svg, history) {
        if (!svg) return;
        if (!history || history.length < 2 || (history.length === 1 && history[0] === 0)) {
            svg.innerHTML = '';
            svg.setAttribute('width', 225);
            svg.setAttribute('height', 170);
            return;
        }
        svg.innerHTML = '';
        const w = 225, h = 170;
        const padX = 8, padTop = 8, padBottom = 8;
        const chartH = h - padTop - padBottom;
        const chartW = w - padX * 2;
        const max = Math.max(...history, 0);
        const min = Math.min(...history, 0);
        const range = (max - min) || 1;
        const toY = (val) => padTop + ((max - val) / range) * chartH;
        const toX = (idx) => padX + (idx / (history.length - 1)) * chartW;
        const zeroY = toY(0);
        const points = history.map((v, i) => ({ x: toX(i), y: toY(v) }));
        let pathD = `M ${points[0].x} ${points[0].y}`;
        if (points.length === 2) {
            pathD += ` L ${points[1].x} ${points[1].y}`;
        } else {
            for (let i = 0; i < points.length - 1; i++) {
                const p0 = points[Math.max(i - 1, 0)];
                const p1 = points[i];
                const p2 = points[i + 1];
                const p3 = points[Math.min(i + 2, points.length - 1)];
                const cp1x = p1.x + (p2.x - p0.x) / 6;
                const cp1y = p1.y + (p2.y - p0.y) / 6;
                const cp2x = p2.x - (p3.x - p1.x) / 6;
                const cp2y = p2.y - (p3.y - p1.y) / 6;
                pathD += ` C ${cp1x}, ${cp1y}, ${cp2x}, ${cp2y}, ${p2.x} ${p2.y}`;
            }
        }
        const last = points[points.length - 1];
        const first = points[0];
        const fillD = pathD + ` L ${last.x} ${zeroY} L ${first.x} ${zeroY}`;
        const positiveMaskH = Math.max(0, Math.min(zeroY, h));
        const negativeMaskY = Math.max(0, Math.min(zeroY, h));
        const negativeMaskH = h - negativeMaskY;
        svg.setAttribute('width', w);
        svg.setAttribute('height', h);
        svg.innerHTML = `
            <mask id="positiveMask"><rect x="0" y="0" fill="white" width="${w}" height="${positiveMaskH}"></rect></mask>
            <path fill="var(--color-green-500)" mask="url(#positiveMask)" fill-opacity="0.2" d="${fillD}"></path>
            <path fill="none" stroke="var(--color-green-500)" mask="url(#positiveMask)" stroke-width="2.5" d="${pathD}"></path>
            <mask id="negativeMask"><rect x="0" fill="white" y="${negativeMaskY}" width="${w}" height="${negativeMaskH}"></rect></mask>
            <path fill="var(--color-red-500)" mask="url(#negativeMask)" fill-opacity="0.2" d="${fillD}"></path>
            <path fill="none" stroke="var(--color-red-500)" mask="url(#negativeMask)" stroke-width="2.5" d="${pathD}"></path>
            <path stroke="grey" stroke-width="1" stroke-opacity="0.5" d="M ${padX} ${zeroY} L ${w - padX} ${zeroY}"></path>
        `;
    }

    function updateStatsDisplay() {
        const profitEl = document.querySelector('[data-testid="bets-stats-profit"]');
        if (!profitEl) return;
        const container = profitEl.closest('div.draggable');
        if (!container) return;
        const wageredEl = container.querySelector('[data-testid="bets-stats-wagered"]');
        const winsEl = container.querySelector('[data-testid="bets-stats-wins"]');
        const lossesEl = container.querySelector('[data-testid="bets-stats-losses"]');
        const svg = container.querySelector('div.graph-wrap svg');
        if (wageredEl && winsEl && lossesEl) {
            const statsCurrency = activeBetSession?.currency || activeGameCurrency || selectedBalanceCurrency || DEFAULT_CURRENCY;
            const fmt = value => formatBalance(Number(value) || 0, statsCurrency);
            profitEl.textContent = fmt(fakeStats.profit);
            profitEl.classList.remove('text-positive', 'text-critical');
            profitEl.classList.add(fakeStats.profit >= 0 ? 'text-positive' : 'text-critical');
            wageredEl.textContent = fmt(fakeStats.wagered);
            winsEl.textContent = fakeStats.wins.toString();
            lossesEl.textContent = fakeStats.losses.toString();
            container.setAttribute('data-athr-display-mode', getDisplayAmountMode());
            container.setAttribute('data-athr-display-currency', getStakeDisplayCurrencyCode(statsCurrency));
            if (svg) drawGraph(svg, fakeStats.profitHistory);
        }
    }

    function createEmptyCryptoBalances() {
        return Object.keys(CRYPTO_CURRENCIES).reduce((balances, code) => {
            balances[code] = 0;
            return balances;
        }, {});
    }

    function loadCryptoBalances(shouldLoad) {
        const balances = createEmptyCryptoBalances();
        if (!shouldLoad) {
            localStorage.removeItem(STORAGE_KEY);
            localStorage.removeItem(CRYPTO_BALANCES_KEY);
            return balances;
        }

        let loadedMultiWallet = false;
        try {
            const stored = localStorage.getItem(CRYPTO_BALANCES_KEY);
            if (stored) {
                const parsed = JSON.parse(stored);
                if (parsed && typeof parsed === 'object') {
                    for (const code of Object.keys(CRYPTO_CURRENCIES)) {
                        const value = Number(parsed[code]);
                        balances[code] = Number.isFinite(value) && value >= 0 ? value : 0;
                    }
                    loadedMultiWallet = true;
                }
            }
        } catch (error) {
            console.warn('[ATHR WALLET] Balance load error:', error);
        }

        if (!loadedMultiWallet) {
            const legacyBalance = Number.parseFloat(localStorage.getItem(STORAGE_KEY));
            if (Number.isFinite(legacyBalance) && legacyBalance >= 0) {
                balances[DEFAULT_CURRENCY] = legacyBalance;
            }
        }
        return balances;
    }

    let settings = loadSettings();
    let stakeFiatRates = loadStakeFiatRateCache();
    let stakeFiatRateUpdatedAt = loadStakeFiatRateCache.updatedAt || { USD: Date.now() };
    let selectedBalanceCurrency = normalizeCurrency(settings.selectedBalanceCurrency);
    let activeGameCurrency = selectedBalanceCurrency;
    let manualActiveCurrency = null;
    let stakeCurrencySyncToken = 0;
    let athrNativeWalletSyncClick = false;
    let currentBetCurrency = null;
    let activeBetSession = null;
    const athrWiringState = {
        observer: null,
        frame: 0,
        followupTimer: 0,
        installed: false,
        reconciling: false,
        reasons: new Set(),
        candidateCurrency: null,
        candidateCount: 0,
        lastConfirmedCurrency: selectedBalanceCurrency,
        pendingTrustedCurrency: null,
        pendingTrustedAt: 0,
        lastInputUsd: null
    };
    let cryptoBalances = loadCryptoBalances(settings.saveBalance);
    let currentBalance = cryptoBalances[activeGameCurrency] || 0;

    function getBetSessionCurrency() {
        return ensureCurrencyRegistered(activeBetSession?.currency)
            || ensureCurrencyRegistered(currentBetCurrency)
            || ensureCurrencyRegistered(activeGameCurrency)
            || selectedBalanceCurrency;
    }

    function refreshBetSessionUI() {
        const locked = !!activeBetSession;
        document.body.classList.toggle('athr-currency-locked', locked);
        if (locked) {
            document.body.setAttribute('data-athr-bet-currency', activeBetSession.currency);
        } else {
            document.body.removeAttribute('data-athr-bet-currency');
        }

        document.querySelectorAll('#athr-coin-grid .athr-coin-btn, #athr-currency-select').forEach(control => {
            control.disabled = locked;
            control.setAttribute('aria-disabled', locked ? 'true' : 'false');
        });

        const sessionLabel = document.getElementById('athr-session-lock');
        if (sessionLabel) {
            const code = locked ? activeBetSession.currency : activeGameCurrency;
            sessionLabel.classList.toggle('is-locked', locked);
            const displayState = getStakeDisplaySyncLabel(code);
            sessionLabel.innerHTML = `${getCurrencyIconSVG(code, 17, 'athr-session-icon')}<span>${locked ? `Bet locked \u00B7 ${displayState} \u00B7 ${code}` : `${displayState} \u00B7 ${code} wallet`}</span>`;
        }
    }

    function beginBetSession(betAmount) {
        if (!isATHRRuntimeActive()) return;
        const minesCount = settings.enableFakeMines ? readATHRMinesControlCount() : null;
        if (settings.enableFakeMines && !Number.isInteger(minesCount)) {
            showErrorNotification('Mines control unavailable or ambiguous. No local round was started.');
            return null;
        }
        syncActiveGameCurrencyFromDOM();
        const activeButton = getActiveCurrencyButton();
        const nativeCurrency = getNativeCurrencyFromToggleButton(activeButton);
        const currency = ensureCurrencyRegistered(manualActiveCurrency)
            || ensureCurrencyRegistered(nativeCurrency)
            || ensureCurrencyRegistered(activeButton?.getAttribute('data-athr-active-currency'))
            || ensureCurrencyRegistered(activeGameCurrency)
            || selectedBalanceCurrency;
        activeBetSession = Object.freeze({
            id: `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
            currency,
            betAmount: Math.max(0, Number(betAmount) || 0),
            minesCount,
            startedAt: Date.now()
        });
        activeGameCurrency = currency;
        currentBalance = getCryptoBalance(currency);
        currentBetCurrency = currency;
        refreshBetSessionUI();
        return activeBetSession;
    }

    function finishBetSession() {
        currentBetCurrency = null;
        activeBetSession = null;
        refreshBetSessionUI();
    }

    function getCryptoBalance(currency) {
        const code = normalizeCurrency(currency);
        const value = Number(cryptoBalances[code]);
        return Number.isFinite(value) && value >= 0 ? value : 0;
    }

    function setCryptoBalance(currency, amount, options = {}) {
        if (!isATHRRuntimeActive()) return;
        const code = normalizeCurrency(currency);
        const numericAmount = Number(amount);
        const next = Number.isFinite(numericAmount) ? Math.max(0, numericAmount) : 0;
        cryptoBalances[code] = next;
        if (code === activeGameCurrency) {
            currentBalance = next;
        }
        if (options.save !== false) {
            saveBalance();
        }
        return next;
    }

    function adjustCryptoBalance(currency, delta, options = {}) {
        if (!isATHRRuntimeActive()) return;
        const code = normalizeCurrency(currency);
        return setCryptoBalance(code, getCryptoBalance(code) + (Number(delta) || 0), options);
    }

    function setSelectedBalanceCurrency(currency, options = {}) {
        const supportedCode = ensureCurrencyRegistered(currency);
        if (!supportedCode) return selectedBalanceCurrency;
        selectedBalanceCurrency = supportedCode;
        settings.selectedBalanceCurrency = selectedBalanceCurrency;
        if (options.persist !== false) {
            persistSettings();
        }
        if (options.update !== false) {
            updateBalanceUI();
        }
        return selectedBalanceCurrency;
    }

    function getNativeCurrencyFromToggleButton(button) {
        if (!button) return null;

        // A visible, unmodified native icon/title is the freshest evidence on
        // Stake's active header control. Its data-testid can lag one render, so
        // never let a stale test id override current visual/native evidence.
        const nativeChoice = isNativeCurrencyChoice(button);
        const managedActiveCode = ensureCurrencyRegistered(button.getAttribute('data-athr-active-currency'));
        const icon = button.querySelector('svg[data-ds-icon]');
        const iconCode = String(icon?.getAttribute('data-ds-icon') || '').toUpperCase();
        const managedIconCode = ensureCurrencyRegistered(icon?.getAttribute('data-athr-icon-rendered'));
        const supportedIconCode = icon && !icon.hasAttribute('data-athr-icon-rendered')
            ? ensureCurrencyRegistered(iconCode)
            : null;
        const titledCode = String(button.querySelector('span[title]')?.getAttribute('title') || '').toUpperCase();
        const supportedTitleCode = ensureCurrencyRegistered(titledCode);
        const dataCode = button.getAttribute('data-currency-code') || button.getAttribute('data-currency');
        const supportedDataCode = ensureCurrencyRegistered(dataCode);
        const testId = button.getAttribute('data-testid') || '';
        const testIdCode = ensureCurrencyRegistered(testId.match(/^coin-toggle-currency-([a-z0-9]+)$/i)?.[1]);

        const recentlyTrustedCode = Date.now() - Number(athrWiringState.pendingTrustedAt || 0) < 900
            ? ensureCurrencyRegistered(athrWiringState.pendingTrustedCurrency)
            : null;
        const evidence = nativeChoice
            ? [supportedIconCode, supportedTitleCode, supportedDataCode, testIdCode]
            : [recentlyTrustedCode, managedIconCode, managedActiveCode, supportedIconCode, supportedTitleCode, supportedDataCode, testIdCode];
        const directCode = evidence.find(Boolean);
        if (directCode) {
            button.setAttribute('data-athr-native-currency', directCode);
            return directCode;
        }

        const labelText = `${button.getAttribute('aria-label') || ''} ${button.textContent || ''}`.toUpperCase();
        const labelCode = SUPPORTED_CURRENCY_CODES.find(code => new RegExp(`(^|[^A-Z0-9])${code}([^A-Z0-9]|$)`).test(labelText));
        if (labelCode) {
            button.setAttribute('data-athr-native-currency', labelCode);
            return labelCode;
        }

        return ensureCurrencyRegistered(button.getAttribute('data-athr-native-currency'));
    }

    function getCurrencyFromToggleButton(button) {
        const nativeCode = getNativeCurrencyFromToggleButton(button);
        if (nativeCode) return nativeCode;
        const remembered = sanitizeCurrencyCode(button?.getAttribute('data-athr-active-currency'));
        return remembered && Object.prototype.hasOwnProperty.call(CRYPTO_CURRENCIES, remembered)
            ? remembered
            : null;
    }

    function isVisibleCurrencyButton(button) {
        if (!button || !button.isConnected) return false;
        const style = window.getComputedStyle(button);
        const rect = button.getBoundingClientRect();
        return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;
    }

    function isNativeCurrencyChoice(button) {
        if (!button) return false;
        if (button.getAttribute('role') === 'option') return true;
        if (button.closest('[role="listbox"], [role="menu"]')) return true;

        const testId = button.getAttribute('data-testid') || '';
        const isCoinToggle = /^coin-toggle-currency-/i.test(testId);
        const isHeaderControl = !!button.closest('header, nav, [data-testid*="header"], [data-testid*="topbar"]');
        const controlsPopup = button.hasAttribute('aria-expanded') || button.hasAttribute('aria-haspopup');
        return isCoinToggle && !isHeaderControl && !controlsPopup && !button.hasAttribute('data-athr-active-currency');
    }

    function scoreActiveCurrencyButton(button) {
        if (!button || !isVisibleCurrencyButton(button) || button.closest('#balance-ui, #athr-wallet-balances-popover')) return Number.NEGATIVE_INFINITY;
        if (button.closest('tr[data-withdrawal-index], tr[data-deposit-index], tr[data-bet-index]')) return Number.NEGATIVE_INFINITY;
        if (!getCurrencyFromToggleButton(button)) return Number.NEGATIVE_INFINITY;

        let score = 20;
        const testId = (button.getAttribute('data-testid') || '').toLowerCase();
        const text = button.textContent || '';
        if (testId === 'coin-toggle') score += 900;
        if (button.closest('#navigation-container-header, [data-testid="balance-toggle"]')) score += 500;
        if (button.hasAttribute('data-athr-active-currency')) score += 1000;
        if (button.hasAttribute('aria-expanded') || button.hasAttribute('aria-haspopup')) score += 320;
        if (button.closest('header, nav, [data-testid*="header"], [data-testid*="topbar"]')) score += 180;
        if (testId.includes('balance') || testId.includes('wallet')) score += 120;
        if (/\$\s*[\d,.]+/.test(text)) score += 55;
        if (/\b\d+\.\d{4,}\b/.test(text)) score += 25;
        if (/^coin-toggle-currency-/i.test(testId)) score -= 40;
        if (isNativeCurrencyChoice(button)) score -= 1000;
        return score;
    }

    function getActiveCurrencyButton() {
        const iconSelector = SUPPORTED_CURRENCY_CODES
            .map(code => `svg[data-ds-icon="${code}"]`)
            .join(',');
        const titleSelector = SUPPORTED_CURRENCY_CODES
            .map(code => `span[title="${code.toLowerCase()}"]`)
            .join(',');
        const candidates = [];
        const seen = new Set();
        const addCandidate = element => {
            const button = element.matches?.('button, [role="button"]')
                ? element
                : element.closest?.('button, [role="button"]');
            if (!button || seen.has(button) || !getCurrencyFromToggleButton(button)) return;
            seen.add(button);
            candidates.push(button);
        };

        document.querySelectorAll(
            'button[data-testid="coin-toggle"], button[data-testid^="coin-toggle-currency-"], button[data-currency-code], button[data-currency], [role="button"][data-currency-code], [role="button"][data-currency], [data-athr-active-currency], [data-athr-native-currency]'
        ).forEach(addCandidate);
        document.querySelectorAll(`${iconSelector}, ${titleSelector}`).forEach(addCandidate);

        const ranked = candidates
            .map(button => ({ button, score: scoreActiveCurrencyButton(button) }))
            .filter(item => Number.isFinite(item.score) && item.score >= 0)
            .sort((a, b) => b.score - a.score);
        return ranked[0]?.button || null;
    }

    function syncActiveGameCurrencyFromDOM() {
        if (activeBetSession) {
            activeGameCurrency = activeBetSession.currency;
            currentBalance = getCryptoBalance(activeGameCurrency);
            return activeGameCurrency;
        }
        const detected = getNativeCurrencyFromToggleButton(getActiveCurrencyButton());
        if (manualActiveCurrency) {
            if (detected === manualActiveCurrency) manualActiveCurrency = null;
            else {
                activeGameCurrency = manualActiveCurrency;
                currentBalance = getCryptoBalance(activeGameCurrency);
                return activeGameCurrency;
            }
        }
        if (detected) {
            if (athrWiringState.candidateCurrency === detected) {
                athrWiringState.candidateCount += 1;
            } else {
                athrWiringState.candidateCurrency = detected;
                athrWiringState.candidateCount = 1;
            }
        }
        const trusted = detected
            && athrWiringState.pendingTrustedCurrency === detected
            && Date.now() - athrWiringState.pendingTrustedAt < 1600;
        const stable = detected
            && (trusted || detected === athrWiringState.lastConfirmedCurrency || athrWiringState.candidateCount >= 2);

        if (stable && detected !== activeGameCurrency) {
            activeGameCurrency = detected;
            selectedBalanceCurrency = detected;
            settings.selectedBalanceCurrency = detected;
            persistSettings();
            currentBalance = getCryptoBalance(activeGameCurrency);
            athrWiringState.lastConfirmedCurrency = detected;
            athrWiringState.pendingTrustedCurrency = null;
            updateCurrencyConversion();
        } else if (stable) {
            athrWiringState.lastConfirmedCurrency = detected;
            athrWiringState.pendingTrustedCurrency = null;
            currentBalance = getCryptoBalance(activeGameCurrency);
        }
        return activeGameCurrency;
    }

    function findStakeCurrencyChoice(currency, activeButton = getActiveCurrencyButton()) {
        const code = normalizeCurrency(currency);
        const lower = code.toLowerCase();
        const candidates = new Set();
        document.querySelectorAll(`button[data-testid="coin-toggle-currency-${lower}"], [data-currency-code="${code}"], [data-currency-code="${lower}"], [data-currency="${code}"], [data-currency="${lower}"]`)
            .forEach(element => candidates.add(element.closest?.('button, [role="option"]') || element));
        document.querySelectorAll(`svg[data-ds-icon="${code}"], span[title="${lower}"]`).forEach(element => {
            const choice = element.closest?.('button, [role="option"]');
            if (choice) candidates.add(choice);
        });
        return Array.from(candidates).find(candidate =>
            candidate !== activeButton &&
            !candidate.closest?.('#balance-ui, #athr-wallet-balances-popover') &&
            isVisibleCurrencyButton(candidate)
        ) || null;
    }

    function syncStakeCurrencyChoice(currency) {
        const code = normalizeCurrency(currency);
        const token = ++stakeCurrencySyncToken;
        const activeButton = getActiveCurrencyButton();
        const focused = document.activeElement;
        if (focused && !focused.closest?.('#balance-ui') && focused.matches?.('input, textarea')) focused.blur();

        const choose = () => {
            if (token !== stakeCurrencySyncToken) return true;
            const choice = findStakeCurrencyChoice(code, activeButton);
            if (!choice) return false;
            choice.click();
            setTimeout(() => {
                const active = document.activeElement;
                if (active && !active.closest?.('#balance-ui') && active.matches?.('input, textarea')) active.blur();
                syncActiveGameCurrencyFromDOM();
                updateBalanceUI();
            }, 90);
            return true;
        };

        if (choose()) return;
        if (activeButton) {
            // Let ATHR open Stake's native wallet menu only for the brief
            // programmatic hand-off needed to select the matching crypto.
            athrNativeWalletSyncClick = true;
            try {
                activeButton.click();
            } finally {
                athrNativeWalletSyncClick = false;
            }
        }
        [70, 160, 320, 520].forEach(delay => setTimeout(() => choose(), delay));
    }

    function setActiveGameCurrency(currency, options = {}) {
        const code = ensureCurrencyRegistered(currency);
        if (!code) return activeGameCurrency;
        if (activeBetSession && code !== activeBetSession.currency && options.forceDuringBet !== true) {
            refreshBetSessionUI();
            return activeBetSession.currency;
        }
        // A trusted Stake wallet choice must immediately replace any temporary
        // ATHR-panel hand-off. Keeping the old manual value here caused the
        // header, bet input and cashout snapshot to jump back to the old coin.
        if (options.transient === true) manualActiveCurrency = code;
        else if (options.manual !== false) manualActiveCurrency = code;
        else manualActiveCurrency = null;
        activeGameCurrency = code;
        currentBalance = getCryptoBalance(code);
        if (options.selectWallet !== false) {
            selectedBalanceCurrency = code;
            settings.selectedBalanceCurrency = code;
            if (options.persist !== false) persistSettings();
        }
        if (options.conversion !== false) updateCurrencyConversion();
        if (options.update !== false) updateBalanceUI();
        if (options.syncStake !== false) syncStakeCurrencyChoice(code);
        return code;
    }

    function adjustActiveGameBalance(delta, options = {}) {
        return adjustCryptoBalance(activeGameCurrency, delta, options);
    }

    let isBalanceUIVisible = settings.showBalanceCard;
    let betHistory = settings.saveBetHistory ? loadStoredBetHistory() : [];
    if (!settings.saveBetHistory) {
        localStorage.removeItem(BET_HISTORY_KEY);
    }

    function loadStoredWithdrawalHistory() {
        try {
            const stored = localStorage.getItem(WITHDRAWAL_HISTORY_KEY);
            if (!stored) return [];
            const parsed = JSON.parse(stored);
            if (Array.isArray(parsed)) {
                return parsed.slice(0, 10).map(entry => {
                    const currency = ensureCurrencyRegistered(entry && entry.currency);
                    if (!currency) return null;
                    return {
                        amount: entry && typeof entry.amount !== 'undefined' ? Number(entry.amount) || 0 : 0,
                        currency,
                        time: entry && entry.time ? entry.time : null,
                        date: entry && entry.date ? entry.date : null,
                        txHash: entry && entry.txHash ? entry.txHash : ''
                    };
                }).filter(Boolean);
            }
        } catch (error) {
            console.warn('Withdrawal history load error:', error);
        }
        return [];
    }

    function loadStoredDepositHistory() {
        try {
            const stored = localStorage.getItem(DEPOSIT_HISTORY_KEY);
            if (!stored) return [];
            const parsed = JSON.parse(stored);
            if (Array.isArray(parsed)) {
                return parsed.slice(0, 10).map(entry => {
                    const currency = ensureCurrencyRegistered(entry && entry.currency);
                    if (!currency) return null;
                    return {
                        amount: entry && typeof entry.amount !== 'undefined' ? Number(entry.amount) || 0 : 0,
                        currency,
                        time: entry && entry.time ? entry.time : null,
                        date: entry && entry.date ? entry.date : null,
                        txHash: entry && entry.txHash ? entry.txHash : ''
                    };
                }).filter(Boolean);
            }
        } catch (error) {
            console.warn('Deposit history load error:', error);
        }
        return [];
    }

    let withdrawalHistory = settings.saveWithdrawalHistory ? loadStoredWithdrawalHistory() : [];
    if (!settings.saveWithdrawalHistory) {
        localStorage.removeItem(WITHDRAWAL_HISTORY_KEY);
    }

    let depositHistory = settings.saveDepositHistory ? loadStoredDepositHistory() : [];
    if (!settings.saveDepositHistory) {
        localStorage.removeItem(DEPOSIT_HISTORY_KEY);
    }

    persistSettings();
    let betHistoryIntervalId = null;
    let withdrawalHistoryIntervalId = null;
    let depositHistoryIntervalId = null;

    // Prefer the userscript transport for optional data/configuration requests;
    // retain fetch as a compatibility fallback where page policy allows it.
    function requestJSON(url, options = {}) {
        const method = String(options.method || 'GET').toUpperCase();
        const headers = { ...(options.headers || {}) };
        const timeout = Math.max(1000, Number(options.timeout) || 12000);
        const data = typeof options.body === 'undefined'
            ? undefined
            : (typeof options.body === 'string' ? options.body : JSON.stringify(options.body));
        const gmRequest = typeof GM_xmlhttpRequest === 'function'
            ? GM_xmlhttpRequest
            : (typeof GM !== 'undefined' && typeof GM.xmlHttpRequest === 'function'
                ? GM.xmlHttpRequest.bind(GM)
                : null);

        if (gmRequest) {
            return new Promise((resolve, reject) => {
                let settled = false;
                const finish = (callback, value) => {
                    if (settled) return;
                    settled = true;
                    callback(value);
                };
                const handleLoad = response => {
                    const status = Number(response?.status) || 0;
                    if (status < 200 || status >= 300) {
                        finish(reject, new Error(`ATHR service returned HTTP ${status || 'error'}`));
                        return;
                    }
                    try {
                        const payload = response?.response && typeof response.response === 'object'
                            ? response.response
                            : JSON.parse(response?.responseText || 'null');
                        finish(resolve, payload);
                    } catch (error) {
                        finish(reject, new Error(`ATHR service returned invalid JSON: ${error.message}`));
                    }
                };
                const handleError = () => finish(reject, new Error('ATHR service is unreachable'));

                try {
                    const maybePromise = gmRequest({
                        method,
                        url,
                        headers,
                        data,
                        timeout,
                        responseType: 'json',
                        anonymous: true,
                        onload: handleLoad,
                        onerror: handleError,
                        onabort: handleError,
                        ontimeout: () => finish(reject, new Error('ATHR service request timed out'))
                    });
                    if (maybePromise && typeof maybePromise.then === 'function') {
                        maybePromise.then(handleLoad, handleError);
                    }
                } catch (error) {
                    finish(reject, error);
                }
            });
        }

        const controller = typeof AbortController === 'function' ? new AbortController() : null;
        const timeoutId = controller ? setTimeout(() => controller.abort(), timeout) : 0;
        return fetch(url, {
            method,
            headers,
            body: data,
            cache: 'no-store',
            credentials: 'omit',
            signal: controller?.signal
        }).then(response => {
            if (!response.ok) throw new Error(`ATHR service returned HTTP ${response.status}`);
            return response.json();
        }).finally(() => {
            if (timeoutId) clearTimeout(timeoutId);
        });
    }

    function loadSettings() {
        const defaults = {
            settingsVersion: 13,
            saveBalance: true,
            saveBetHistory: false,
            saveWithdrawalHistory: true,
            showBalanceCard: true,
            enableFakeMines: true,
            enableFakeBalance: true,
            enableFakeWithdrawals: true,
            selectedWithdrawalCurrency: DEFAULT_CURRENCY,
            saveDepositHistory: true,
            enableFakeDeposits: true,
            selectedDepositCurrency: DEFAULT_CURRENCY,
            selectedBalanceCurrency: DEFAULT_CURRENCY,
            displayAmountMode: 'USD',
            localCurrencyCode: 'INR',
            localCurrencySymbol: '\u20B9',
            localCurrencyRate: 0,
            localCurrencyRateCode: 'INR',
            enablePredictor: false,
            preDecideBombLocations: true,
            locationEditorMode: 'bomb',
            customBombLocations: [],
            customGemLocations: [],
            customName: 'ATHR',
            telegramTagName: 'xosystem',
            predictorColor: '#c084fc',
            stakeDisplayName: 'OlaKira',
            // Captured from the user-supplied ATHR VIP diagnostic. It remains
            // editable and is used only as the source text for local privacy.
            stakeSourceUsername: 'OlaKira',
            stakeUsernameHide: false,
            stakeUsernameBlur: false,
            stakeUsernameRgb: true,
            stakeUsernameGlow: false,
            stakeUsernameFade: false,
            stakeUsernameBlurIntensity: 8,
            stakeUsernameAnimationSpeed: 3,
            showVipCard: false,
            vipProgress: 9.15,
            vipWager: 0,
            vipRank: 'Unranked',
            vipNextLevel: 'Bronze',
            uiTheme: 'midnight-cyan',
            showBrandLogo: false
        };

        try {
            const stored = localStorage.getItem(SETTINGS_KEY);
            if (stored) {
                const parsed = JSON.parse(stored);
                if (parsed && typeof parsed === 'object') {
                    const restoreFakeTransactions = Number(parsed.settingsVersion || 0) < 2;
                    const restorePanelVisibility = Number(parsed.settingsVersion || 0) < 8;
                    const removeLegacyBrandLogo = Number(parsed.settingsVersion || 0) < 13;
                    const parsedLocalSymbol = typeof parsed.localCurrencySymbol === 'string'
                        ? parsed.localCurrencySymbol.trim().slice(0, 6)
                        : '';
                    const safeLocalSymbol = /[\u00c2\u00c3\u00e2\ufffd]/u.test(parsedLocalSymbol)
                        ? defaults.localCurrencySymbol
                        : (parsedLocalSymbol || defaults.localCurrencySymbol);
                    const parsedStakeSourceUsername = typeof parsed.stakeSourceUsername === 'string'
                        ? parsed.stakeSourceUsername.trim().slice(0, 64)
                        : '';
                    const safeStakeSourceUsername = /^[A-Za-z0-9_.-]{2,64}$/u.test(parsedStakeSourceUsername)
                        ? parsedStakeSourceUsername
                        : defaults.stakeSourceUsername;
                    return {
                        settingsVersion: defaults.settingsVersion,
                        saveBalance: typeof parsed.saveBalance === 'boolean' ? parsed.saveBalance : defaults.saveBalance,
                        saveBetHistory: typeof parsed.saveBetHistory === 'boolean' ? parsed.saveBetHistory : defaults.saveBetHistory,
                        saveWithdrawalHistory: restoreFakeTransactions ? true : (typeof parsed.saveWithdrawalHistory === 'boolean' ? parsed.saveWithdrawalHistory : defaults.saveWithdrawalHistory),
                        // v5.4.7 performs a one-time visibility recovery so the
                        // newly local startup always opens the control deck once.
                        showBalanceCard: restorePanelVisibility
                            ? true
                            : (typeof parsed.showBalanceCard === 'boolean' ? parsed.showBalanceCard : defaults.showBalanceCard),
                        enableFakeMines: typeof parsed.enableFakeMines === 'boolean' ? parsed.enableFakeMines : defaults.enableFakeMines,
                        enableFakeBalance: typeof parsed.enableFakeBalance === 'boolean' ? parsed.enableFakeBalance : defaults.enableFakeBalance,
                        enableFakeWithdrawals: restoreFakeTransactions ? true : (typeof parsed.enableFakeWithdrawals === 'boolean' ? parsed.enableFakeWithdrawals : defaults.enableFakeWithdrawals),
                        selectedWithdrawalCurrency: normalizeCurrency(parsed.selectedWithdrawalCurrency),
                        saveDepositHistory: restoreFakeTransactions ? true : (typeof parsed.saveDepositHistory === 'boolean' ? parsed.saveDepositHistory : defaults.saveDepositHistory),
                        enableFakeDeposits: restoreFakeTransactions ? true : (typeof parsed.enableFakeDeposits === 'boolean' ? parsed.enableFakeDeposits : defaults.enableFakeDeposits),
                        selectedDepositCurrency: normalizeCurrency(parsed.selectedDepositCurrency),
                        selectedBalanceCurrency: normalizeCurrency(parsed.selectedBalanceCurrency),
                        displayAmountMode: ['USD', 'LOCAL', 'CRYPTO'].includes(String(parsed.displayAmountMode || '').toUpperCase())
                            ? String(parsed.displayAmountMode).toUpperCase()
                            : defaults.displayAmountMode,
                        localCurrencyCode: /^[A-Z]{2,6}$/.test(String(parsed.localCurrencyCode || '').toUpperCase())
                            ? String(parsed.localCurrencyCode).toUpperCase()
                            : defaults.localCurrencyCode,
                        localCurrencySymbol: safeLocalSymbol,
                        localCurrencyRate: Number.isFinite(Number(parsed.localCurrencyRate)) && Number(parsed.localCurrencyRate) > 0
                            ? Number(parsed.localCurrencyRate)
                            : defaults.localCurrencyRate,
                        localCurrencyRateCode: /^[A-Z]{2,6}$/.test(String(parsed.localCurrencyRateCode || parsed.localCurrencyCode || '').toUpperCase())
                            ? String(parsed.localCurrencyRateCode || parsed.localCurrencyCode).toUpperCase()
                            : defaults.localCurrencyRateCode,
                        enablePredictor: typeof parsed.enablePredictor === 'boolean' ? parsed.enablePredictor : defaults.enablePredictor,
                        preDecideBombLocations: typeof parsed.preDecideBombLocations === 'boolean' ? parsed.preDecideBombLocations : defaults.preDecideBombLocations,
                        locationEditorMode: parsed.locationEditorMode === 'gem' ? 'gem' : defaults.locationEditorMode,
                        customBombLocations: Array.isArray(parsed.customBombLocations) ? parsed.customBombLocations : defaults.customBombLocations,
                        customGemLocations: Array.isArray(parsed.customGemLocations) ? parsed.customGemLocations : defaults.customGemLocations,
                        customName: typeof parsed.customName === 'string' && !/^popper larps?$/i.test(parsed.customName.trim()) ? parsed.customName : defaults.customName,
                        telegramTagName: typeof parsed.telegramTagName === 'string' ? parsed.telegramTagName : defaults.telegramTagName,
                        predictorColor: typeof parsed.predictorColor === 'string' ? parsed.predictorColor : defaults.predictorColor,
                        stakeDisplayName: typeof parsed.stakeDisplayName === 'string' && parsed.stakeDisplayName.trim() ? parsed.stakeDisplayName.trim().slice(0, 24) : defaults.stakeDisplayName,
                        stakeSourceUsername: safeStakeSourceUsername,
                        stakeUsernameHide: typeof parsed.stakeUsernameHide === 'boolean' ? parsed.stakeUsernameHide : defaults.stakeUsernameHide,
                        stakeUsernameBlur: typeof parsed.stakeUsernameBlur === 'boolean' ? parsed.stakeUsernameBlur : defaults.stakeUsernameBlur,
                        stakeUsernameRgb: typeof parsed.stakeUsernameRgb === 'boolean' ? parsed.stakeUsernameRgb : defaults.stakeUsernameRgb,
                        stakeUsernameGlow: typeof parsed.stakeUsernameGlow === 'boolean' ? parsed.stakeUsernameGlow : defaults.stakeUsernameGlow,
                        stakeUsernameFade: typeof parsed.stakeUsernameFade === 'boolean' ? parsed.stakeUsernameFade : defaults.stakeUsernameFade,
                        stakeUsernameBlurIntensity: Number.isFinite(Number(parsed.stakeUsernameBlurIntensity)) ? Math.min(20, Math.max(1, Number(parsed.stakeUsernameBlurIntensity))) : defaults.stakeUsernameBlurIntensity,
                        stakeUsernameAnimationSpeed: Number.isFinite(Number(parsed.stakeUsernameAnimationSpeed)) ? Math.min(10, Math.max(1, Number(parsed.stakeUsernameAnimationSpeed))) : defaults.stakeUsernameAnimationSpeed,
                        showVipCard: false,
                        vipProgress: Number.isFinite(Number(parsed.vipProgress)) ? Math.min(100, Math.max(0, Number(parsed.vipProgress))) : defaults.vipProgress,
                        vipWager: Number.isFinite(Number(parsed.vipWager)) ? Math.max(0, Number(parsed.vipWager)) : defaults.vipWager,
                        vipRank: typeof parsed.vipRank === 'string' && parsed.vipRank.trim() ? parsed.vipRank.trim().slice(0, 24) : defaults.vipRank,
                        vipNextLevel: typeof parsed.vipNextLevel === 'string' && parsed.vipNextLevel.trim() ? parsed.vipNextLevel.trim().slice(0, 24) : defaults.vipNextLevel,
                        uiTheme: ['midnight-cyan', 'neon-emerald', 'royal-violet'].includes(String(parsed.uiTheme || '').toLowerCase())
                            ? String(parsed.uiTheme).toLowerCase()
                            : defaults.uiTheme,
                        showBrandLogo: removeLegacyBrandLogo
                            ? false
                            : (typeof parsed.showBrandLogo === 'boolean' ? parsed.showBrandLogo : defaults.showBrandLogo)
                    };
                }
            }
        } catch (error) {
            console.warn('Settings load error:', error);
        }

        return { ...defaults };
    }

    function persistSettings() {
        if (!isATHRRuntimeActive()) return;
        try {
            localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
        } catch (error) {
            console.warn('Settings save error:', error);
        }
    }

    function escapeHTML(value) {
        return String(value ?? '')
            .replaceAll('&', '&amp;')
            .replaceAll('<', '&lt;')
            .replaceAll('>', '&gt;')
            .replaceAll('"', '&quot;')
            .replaceAll("'", '&#039;');
    }

    const VIP_DIAMOND_SVG = `<svg data-ds-icon="VIPDiamondI" width="40" height="40" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" fill="none" aria-hidden="true">
        <path fill="#bde9ff" d="M19.214 3.5a52 52 0 0 1-14.437 0L1 8.843 12 20.5 23 8.843z"></path>
        <path fill="#fff" d="M7.343 11.488 12 20.5l4.657-9.012s-5.308-1.594-9.314 0"></path>
        <path fill="#b0b8fc" d="M4.786 3.5s6.096.41 7.214 2.458c0 0-2.86 5.334-4.657 5.53 0 0-3.364-5.93-2.557-7.98z"></path>
        <path fill="#fff" d="m12 5.958-4.657 5.53h9.314z"></path>
        <path fill="#b0b8fc" d="M23 8.843 12 20.5l4.657-9.012z"></path>
        <path fill="#bde9ff" d="M1 8.843 12 20.5l-4.657-9.012z"></path>
        <path fill="#b0b8fc" d="m4.786 3.5 2.557 7.988L1 8.843z"></path>
        <path fill="#fff" d="m19.214 3.5-2.557 7.988L23 8.843zm-14.428 0L12 5.958 19.214 3.5z"></path>
        <path fill="#000" d="M10.753 5.77h2.494v8.016h-2.494z"></path>
    </svg>`;

    // This is the only VIP-specific SVG present in the supplied capture. Rank
    // badges were not present on that page, so the local preview never invents
    // or presents an uncaptured badge as genuine Stake account state.
    const CAPTURED_VIP_HOST_SVG = `<svg data-ds-icon="VIPHost" width="16" height="16" viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg" fill="none" aria-hidden="true"><path fill="currentColor" d="M13.04 1.48h-.25l-2.83 1-2.83-1a.9.9 0 0 0-1.17.75v2.08c0 .59.5 1 1 1h.25l2.75-1.25 2.83 1.25c.58.17 1.08-.16 1.25-.75V2.48c0-.58-.5-1-1-1m-4.5 15.75L4.8 4.73c-.25-.5-.75-.75-1.33-.58l-1.25.41c-.42.09-.67.5-.67.92l-.75 12c0 .58.42 1 .92 1.08h5.83c.58 0 1-.41 1-1 .08-.08 0-.25 0-.33m9.83-11.75q-.02-.65-.67-.92l-1.25-.5c-.5-.16-1.08.09-1.25.59l-3.75 12.5c-.17.5.17 1.08.67 1.25.08 0 .16.08.33.08h5.75c.58 0 1-.42 1-1z"></path></svg>`;
    const ATHR_LOCAL_VIP_RANKS = Object.freeze([
        'Unranked', 'Bronze', 'Silver', 'Gold',
        'Platinum I', 'Platinum II', 'Platinum III',
        'Diamond I', 'Diamond II', 'Diamond III', 'Obsidian'
    ]);

    function renderLocalVipRankOptions() {
        const selected = String(settings.vipRank || 'Unranked');
        const ranks = ATHR_LOCAL_VIP_RANKS.includes(selected)
            ? ATHR_LOCAL_VIP_RANKS
            : [selected, ...ATHR_LOCAL_VIP_RANKS];
        return ranks.map(rank =>
            `<option value="${escapeHTML(rank)}" ${rank === selected ? 'selected' : ''}>${escapeHTML(rank)}</option>`
        ).join('');
    }

    function renderVipProfileHTML() {
        return '';
    }

    const ATHR_VIP_SURFACE_SIGNALS = Object.freeze([
        'monthly bonus', 'rakeback', 'weekly boost', 'reload',
        'vip host', 'unlock vip benefits', 'next level'
    ]);

    function getATHRVipSurfaceScore(element) {
        if (!(element instanceof Element)) return 0;
        const text = normalizeStakeIdentityText(element.textContent).toLocaleLowerCase();
        if (!text) return 0;
        return ATHR_VIP_SURFACE_SIGNALS.reduce(
            (score, signal) => score + (text.includes(signal) ? 1 : 0),
            0
        );
    }

    function findATHRStakeVipSurface(root = document) {
        if (!root?.querySelectorAll) return null;
        const titleSelector = 'h1, h2, h3, [role="heading"], [data-ds-text="true"]';
        const titleNodes = [];
        if (root.nodeType === Node.ELEMENT_NODE && root.matches?.(titleSelector)) titleNodes.push(root);
        root.querySelectorAll(titleSelector).forEach(element => titleNodes.push(element));

        for (const title of titleNodes) {
            if (title.closest('#balance-ui, #athr-secure-access, [data-athr-local-vip-preview="true"]')) continue;
            if (normalizeStakeIdentityText(title.textContent).toLocaleLowerCase() !== 'vip') continue;
            let candidate = title.parentElement;
            for (let depth = 0; candidate && candidate !== document.body && depth < 12; depth += 1, candidate = candidate.parentElement) {
                if (candidate.closest('#balance-ui, #athr-secure-access')) break;
                if (getATHRVipSurfaceScore(candidate) >= 2) return candidate;
            }
        }

        const modalSelector = '[role="dialog"], [aria-modal="true"], [data-modal-card="true"]';
        const modals = [];
        if (root.nodeType === Node.ELEMENT_NODE && root.matches?.(modalSelector)) modals.push(root);
        root.querySelectorAll(modalSelector).forEach(element => modals.push(element));
        return modals.find(element => {
            if (element.closest('#balance-ui, #athr-secure-access') || getATHRVipSurfaceScore(element) < 2) return false;
            return Array.from(element.querySelectorAll(titleSelector)).some(title =>
                !title.closest('[data-athr-local-vip-preview="true"]')
                && normalizeStakeIdentityText(title.textContent).toLocaleLowerCase() === 'vip'
            );
        }) || null;
    }

    function findATHRVipPreviewInsertion(surface) {
        if (!surface?.querySelectorAll) return null;
        const textSelector = 'h1, h2, h3, h4, [role="heading"], [data-ds-text="true"], span, strong, button';
        const nodes = Array.from(surface.querySelectorAll(textSelector))
            .filter(element => !element.closest('[data-athr-local-vip-preview="true"]'));
        const monthly = nodes.find(element => normalizeStakeIdentityText(element.textContent).toLocaleLowerCase() === 'monthly bonus');
        const rakeback = nodes.find(element => normalizeStakeIdentityText(element.textContent).toLocaleLowerCase() === 'rakeback');
        if (!monthly || !rakeback) return null;

        const monthlyAncestors = new Set();
        for (let node = monthly; node && node !== surface.parentElement; node = node.parentElement) monthlyAncestors.add(node);
        let common = rakeback;
        while (common && !monthlyAncestors.has(common)) common = common.parentElement;
        if (!common || common === document.body || !surface.contains(common)) return null;

        let anchor = monthly;
        while (anchor.parentElement && anchor.parentElement !== common) anchor = anchor.parentElement;
        return anchor.parentElement ? { parent: anchor.parentElement, anchor } : null;
    }

    function syncATHRStakeVipPreview(root = document) {
        document.querySelectorAll('#athr-vip-card, [data-athr-stake-profile-preview="true"]')
            .forEach(card => card.remove());
        return null;
    }

    function refreshATHRVipPreviewUsername(nameElement) {
        if (!nameElement) return;
        const replacementText = settings.stakeUsernameHide
            ? '******'
            : normalizeStakeIdentityText(settings.stakeDisplayName || settings.stakeSourceUsername || 'ATHR Player');
        clearATHRUsernamePresentation(nameElement);
        nameElement.textContent = replacementText;
        nameElement.classList.toggle('athr-username-blur', !!settings.stakeUsernameBlur);
        nameElement.classList.toggle('athr-username-rgb', !!settings.stakeUsernameRgb);
        nameElement.classList.toggle('athr-username-glow', !!settings.stakeUsernameGlow);
        nameElement.classList.toggle('athr-username-fade', !!settings.stakeUsernameFade);
        nameElement.style.setProperty('--athr-username-blur', `${Math.min(20, Math.max(1, Number(settings.stakeUsernameBlurIntensity) || 8))}px`);
        const animationSpeed = Math.min(10, Math.max(1, Number(settings.stakeUsernameAnimationSpeed) || 3));
        nameElement.style.setProperty('--athr-username-speed', `${animationSpeed}s`);
        const animations = [];
        if (settings.stakeUsernameRgb) animations.push(`athrV46Rgb ${animationSpeed}s linear infinite`);
        if (settings.stakeUsernameGlow) animations.push(`athrUsernameGlow ${animationSpeed}s ease-in-out infinite`);
        if (settings.stakeUsernameFade) animations.push(`athrUsernameFade ${animationSpeed}s ease-in-out infinite`);
        if (animations.length) nameElement.style.setProperty('animation', animations.join(', '), 'important');
        if (settings.stakeUsernameHide) nameElement.setAttribute('aria-label', 'Username hidden by ATHR');
        else nameElement.removeAttribute('aria-label');
    }

    function refreshVipProfile() {
        const progress = Math.min(100, Math.max(0, Number(settings.vipProgress) || 0));
        const card = syncATHRStakeVipPreview(document);
        if (card) card.style.display = 'block';
        const name = document.getElementById('athr-vip-name');
        const rank = document.getElementById('athr-vip-rank');
        if (rank) rank.textContent = settings.vipRank;
        const summaryRank = document.getElementById('athr-vip-summary-rank');
        if (summaryRank) summaryRank.textContent = settings.vipRank;
        const wager = document.getElementById('athr-vip-wager');
        if (wager) wager.textContent = `${formatBalance(Number(settings.vipWager) || 0)} wagered`;
        const percent = document.getElementById('athr-vip-percent');
        if (percent) percent.textContent = `${progress.toFixed(2)}%`;
        const bar = document.getElementById('athr-vip-progress');
        if (bar) bar.style.width = `${progress}%`;
        const next = document.getElementById('athr-vip-next-level');
        if (next) next.textContent = settings.vipNextLevel;
        applyStakeUsernameCustomization(document);
        refreshATHRVipPreviewUsername(name);
    }

    const STAKE_USERNAME_PRIMARY_SELECTOR = 'span.text-neutral-default.edge-typography-body-md-strong[data-ds-text="true"], span.edge-typography-body-md-strong[data-ds-text="true"], [data-username], [data-user-name], [data-testid*="username" i], [data-testid*="user-name" i], a[href*="/user/" i]';
    const STAKE_USERNAME_CANDIDATE_SELECTOR = 'span[data-ds-text="true"], a[data-ds-text="true"], [data-username], [data-user-name], [data-testid*="username" i], [data-testid*="user-name" i], a[href*="/user/" i], [title], [aria-label], [alt]';
    // Tooltips and portals are intentionally not excluded: Stake repeats the
    // signed-in name in those surfaces. Monetary controls stay protected so a
    // username that happens to resemble a currency can never touch balances.
    const STAKE_USERNAME_EXCLUSION_SELECTOR = '#balance-ui, #predictor-radar-container, #athr-secure-access, [data-athr-local-vip-preview="true"], [data-testid="modal-wallet"], .currencies, [data-testid="balance-toggle"], [data-testid="coin-toggle"], [data-testid^="coin-toggle-currency-"]';
    const STAKE_USERNAME_TEXT_SKIP_SELECTOR = `${STAKE_USERNAME_EXCLUSION_SELECTOR}, script, style, noscript, svg, canvas, input, textarea, select, option, [contenteditable]:not([contenteditable="false"]), [data-athr-username-target="true"]`;
    const STAKE_USERNAME_ATTRIBUTE_NAMES = Object.freeze(['title', 'aria-label', 'alt', 'data-username', 'data-user-name']);
    const CAPTURED_STAKE_USERNAME = 'OlaKira';
    let stakeIdentityObserver = null;
    let legacyUsernameMutationsRepaired = false;

    function normalizeStakeIdentityText(value) {
        return String(value || '').replace(/\s+/g, ' ').trim();
    }

    function isSameStakeIdentity(left, right) {
        const a = normalizeStakeIdentityText(left);
        const b = normalizeStakeIdentityText(right);
        return !!a && !!b && a.toLocaleLowerCase() === b.toLocaleLowerCase();
    }

    function escapeStakeIdentityRegExp(value) {
        return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    function isSafeStakeIdentityText(value) {
        const text = normalizeStakeIdentityText(value);
        return !!text && !/[\u00c2\u00c3\u00e2\ufffd]/u.test(text) && !/^\*{3,}$/u.test(text);
    }

    function clearATHRUsernamePresentation(element) {
        element.classList.remove('athr-username-blur', 'athr-username-rgb', 'athr-username-glass', 'athr-username-glow', 'athr-username-fade');
        element.style.removeProperty('--athr-username-blur');
        element.style.removeProperty('--athr-username-speed');
        element.style.removeProperty('animation');
        element.style.removeProperty('filter');
        element.style.removeProperty('-webkit-filter');
        element.style.removeProperty('backdrop-filter');
        element.style.removeProperty('-webkit-backdrop-filter');
        element.style.removeProperty('text-shadow');
    }

    function restoreLegacyUsernameMutations() {
        if (legacyUsernameMutationsRepaired || !document.querySelectorAll) return;
        legacyUsernameMutationsRepaired = true;
        const legacySelector = '[data-athr-username-target], [data-athr-original-username], .athr-username-blur, .athr-username-rgb, .athr-username-glass, .athr-username-glow, .athr-username-fade';
        document.querySelectorAll(legacySelector).forEach(element => {
            if (element.closest('[data-athr-local-vip-preview="true"]')) return;
            const original = normalizeStakeIdentityText(element.getAttribute('data-athr-original-username'));
            const configuredSource = getConfiguredStakeSourceUsername();
            if (isSafeStakeIdentityText(original)) element.textContent = original;
            else if (isSafeStakeIdentityText(configuredSource)) element.textContent = configuredSource;
            clearATHRUsernamePresentation(element);
            if ((element.getAttribute('aria-label') || '') === 'Username hidden by ATHR') element.removeAttribute('aria-label');
            if ((element.getAttribute('title') || '') === 'ATHR privacy protection enabled') element.removeAttribute('title');
            element.removeAttribute('data-athr-username-target');
            element.removeAttribute('data-athr-original-username');
        });
    }

    function restoreATHRManagedUsernames() {
        // Partial-text matches are wrapped in a small span. Unwrap those first
        // so changing the configured source restores the exact Stake sentence.
        document.querySelectorAll?.('[data-athr-username-inline="true"]').forEach(element => {
            const original = normalizeStakeIdentityText(element.getAttribute('data-athr-original-username'));
            const parent = element.parentNode;
            element.replaceWith(document.createTextNode(isSafeStakeIdentityText(original) ? original : (element.textContent || '')));
            parent?.normalize?.();
        });
        document.querySelectorAll?.('[data-athr-username-target="true"]:not([data-athr-username-inline="true"])').forEach(element => {
            const original = normalizeStakeIdentityText(element.getAttribute('data-athr-original-username'));
            if (isSafeStakeIdentityText(original)) element.textContent = original;
            clearATHRUsernamePresentation(element);
            element.removeAttribute('data-athr-username-target');
            element.removeAttribute('data-athr-original-username');
            if ((element.getAttribute('aria-label') || '') === 'Username hidden by ATHR') element.removeAttribute('aria-label');
        });
        document.querySelectorAll?.('[data-athr-username-attributes]').forEach(element => {
            const names = String(element.getAttribute('data-athr-username-attributes') || '')
                .split(',')
                .map(name => name.trim())
                .filter(name => STAKE_USERNAME_ATTRIBUTE_NAMES.includes(name));
            names.forEach(name => {
                const storageName = `data-athr-original-attr-${name}`;
                const original = element.getAttribute(storageName);
                if (original !== null) element.setAttribute(name, original);
                element.removeAttribute(storageName);
            });
            element.removeAttribute('data-athr-username-attributes');
        });
    }

    function isPlausibleStakeUsername(value) {
        const text = normalizeStakeIdentityText(value);
        return /^[A-Za-z0-9_.-]{2,64}$/u.test(text)
            && !SUPPORTED_CURRENCY_SET.has(text.toUpperCase())
            && !/^(?:mines|stake|wallet|balance|cashout|bet|anonymous)$/i.test(text);
    }

    function getConfiguredStakeSourceUsername() {
        const candidates = [settings.stakeSourceUsername, GM_getValue('stakeUsername')];
        return candidates.map(normalizeStakeIdentityText).find(isPlausibleStakeUsername) || '';
    }

    function getStakeSourceUsernameCandidates() {
        const values = [settings.stakeSourceUsername, GM_getValue('stakeUsername'), CAPTURED_STAKE_USERNAME]
            .map(normalizeStakeIdentityText)
            .filter(isPlausibleStakeUsername);
        const seen = new Set();
        return values.filter(value => {
            const key = value.toLocaleLowerCase();
            if (seen.has(key)) return false;
            seen.add(key);
            return true;
        });
    }

    function replaceStakeUsernameOccurrence(value, source, replacement) {
        const raw = String(value || '');
        const pattern = new RegExp(`(^|[^A-Za-z0-9_.-])(${escapeStakeIdentityRegExp(source)})(?=$|[^A-Za-z0-9_.-])`, 'giu');
        return raw.replace(pattern, (_match, prefix) => `${prefix}${replacement}`);
    }

    function applyStakeUsernameAttributes(root, configuredSource) {
        if (!root || !configuredSource) return 0;
        const replacement = settings.stakeUsernameHide
            ? '******'
            : normalizeStakeIdentityText(settings.stakeDisplayName || configuredSource);
        const selector = STAKE_USERNAME_ATTRIBUTE_NAMES.map(name => `[${name}]`).join(',');
        const elements = new Set();
        if (root.nodeType === Node.ELEMENT_NODE && root.matches?.(selector)) elements.add(root);
        root.querySelectorAll?.(selector).forEach(element => elements.add(element));
        let updated = 0;

        elements.forEach(element => {
            if (element.closest(STAKE_USERNAME_EXCLUSION_SELECTOR)) return;
            const managed = new Set(String(element.getAttribute('data-athr-username-attributes') || '').split(',').filter(Boolean));
            STAKE_USERNAME_ATTRIBUTE_NAMES.forEach(name => {
                const current = element.getAttribute(name);
                if (current === null) return;
                const storageName = `data-athr-original-attr-${name}`;
                const stored = element.getAttribute(storageName);
                const sourceValue = stored === null ? current : stored;
                const next = replaceStakeUsernameOccurrence(sourceValue, configuredSource, replacement);
                if (next === sourceValue && !isSameStakeIdentity(sourceValue, configuredSource)) return;
                if (stored === null) element.setAttribute(storageName, sourceValue);
                if (current !== next) element.setAttribute(name, next);
                managed.add(name);
                updated += 1;
            });
            if (managed.size) element.setAttribute('data-athr-username-attributes', Array.from(managed).join(','));
        });
        return updated;
    }

    function isExactStakeUsernameTarget(element, configuredSource) {
        if (!(element instanceof Element) || !configuredSource) return false;
        if (element.closest(STAKE_USERNAME_EXCLUSION_SELECTOR)) return false;
        if (element.children.length > 0 && !element.matches('[data-username], [data-user-name]')) return false;
        const source = normalizeStakeIdentityText(configuredSource);
        const visible = normalizeStakeIdentityText(element.textContent);
        const original = normalizeStakeIdentityText(element.getAttribute('data-athr-original-username'));
        const dataUsername = normalizeStakeIdentityText(element.getAttribute('data-username') || element.getAttribute('data-user-name'));
        return isSameStakeIdentity(visible, source)
            || isSameStakeIdentity(original, source)
            || isSameStakeIdentity(dataUsername, source);
    }

    function applyStakeUsernameTarget(element, sourceOverride = '') {
        if (!(element instanceof Element) || element.closest(STAKE_USERNAME_EXCLUSION_SELECTOR)) return false;
        if (element.children.length > 0 && !element.matches('[data-username], [data-user-name]')) return false;

        const existingOriginal = normalizeStakeIdentityText(element.getAttribute('data-athr-original-username'));
        const visible = normalizeStakeIdentityText(element.textContent);
        const originalUsername = existingOriginal || normalizeStakeIdentityText(sourceOverride) || visible;
        if (!isPlausibleStakeUsername(originalUsername)) return false;

        if (!existingOriginal) element.setAttribute('data-athr-original-username', originalUsername);
        if (!isPlausibleStakeUsername(settings.stakeSourceUsername)) {
            settings.stakeSourceUsername = originalUsername;
            const sourceInput = document.getElementById('stake-source-username-input');
            if (sourceInput && sourceInput.value !== originalUsername) sourceInput.value = originalUsername;
            persistSettings();
        }
        if (!isPlausibleStakeUsername(GM_getValue('stakeUsername'))) GM_setValue('stakeUsername', originalUsername);

        // ASCII masking avoids the old UTF-8 garbled-bullet text seen
        // on some Android WebViews while remaining identical on every device.
        const replacementText = settings.stakeUsernameHide
            ? '******'
            : normalizeStakeIdentityText(settings.stakeDisplayName || originalUsername);
        const blurIntensity = Math.min(20, Math.max(1, Number(settings.stakeUsernameBlurIntensity) || 8));
        const animationSpeed = Math.min(10, Math.max(1, Number(settings.stakeUsernameAnimationSpeed) || 3));

        element.setAttribute('data-athr-username-target', 'true');
        if (normalizeStakeIdentityText(element.textContent) !== replacementText) element.textContent = replacementText;
        element.classList.toggle('athr-username-blur', !!settings.stakeUsernameBlur);
        element.classList.toggle('athr-username-rgb', !!settings.stakeUsernameRgb);
        element.classList.toggle('athr-username-glow', !!settings.stakeUsernameGlow);
        element.classList.toggle('athr-username-fade', !!settings.stakeUsernameFade);
        element.style.setProperty('--athr-username-blur', `${blurIntensity}px`);
        element.style.setProperty('--athr-username-speed', `${animationSpeed}s`);
        const animations = [];
        if (settings.stakeUsernameRgb) animations.push(`athrV46Rgb ${animationSpeed}s linear infinite`);
        if (settings.stakeUsernameGlow) animations.push(`athrUsernameGlow ${animationSpeed}s ease-in-out infinite`);
        if (settings.stakeUsernameFade) animations.push(`athrUsernameFade ${animationSpeed}s ease-in-out infinite`);
        if (animations.length) element.style.setProperty('animation', animations.join(', '), 'important');
        else element.style.removeProperty('animation');
        if (settings.stakeUsernameHide) element.setAttribute('aria-label', 'Username hidden by ATHR');
        else if ((element.getAttribute('aria-label') || '') === 'Username hidden by ATHR') element.removeAttribute('aria-label');
        if ((element.getAttribute('title') || '') === 'ATHR privacy protection enabled') element.removeAttribute('title');
        return true;
    }

    function applyStakeUsernameTextNodes(root, configuredSource) {
        if (!root || !configuredSource || !document.createTreeWalker) return 0;
        const scanRoot = root.nodeType === Node.TEXT_NODE ? root.parentElement : root;
        if (!scanRoot || (scanRoot.nodeType !== Node.ELEMENT_NODE && scanRoot.nodeType !== Node.DOCUMENT_NODE)) return 0;
        if (scanRoot.nodeType === Node.ELEMENT_NODE && scanRoot.closest?.(STAKE_USERNAME_TEXT_SKIP_SELECTOR)) return 0;

        const source = normalizeStakeIdentityText(configuredSource);
        const sourceLower = source.toLocaleLowerCase();
        if (!sourceLower || !String(scanRoot.textContent || '').toLocaleLowerCase().includes(sourceLower)) return 0;

        const walker = document.createTreeWalker(scanRoot, NodeFilter.SHOW_TEXT);
        const textNodes = [];
        let node;
        while ((node = walker.nextNode())) textNodes.push(node);
        let updated = 0;

        textNodes.forEach(textNode => {
            const parent = textNode.parentElement;
            const rawText = String(textNode.nodeValue || '');
            if (!parent || parent.closest?.(STAKE_USERNAME_TEXT_SKIP_SELECTOR)) return;
            if (!rawText.toLocaleLowerCase().includes(sourceLower)) return;

            if (isSameStakeIdentity(rawText, source) && parent.children.length === 0 && parent.childNodes.length === 1) {
                if (applyStakeUsernameTarget(parent, source)) updated += 1;
                return;
            }

            const pattern = new RegExp(`(^|[^A-Za-z0-9_.-])(${escapeStakeIdentityRegExp(source)})(?=$|[^A-Za-z0-9_.-])`, 'giu');
            const fragment = document.createDocumentFragment();
            const usernameSpans = [];
            let cursor = 0;
            let match;
            while ((match = pattern.exec(rawText))) {
                const matchedName = match[2];
                const nameStart = match.index + match[1].length;
                if (nameStart > cursor) fragment.appendChild(document.createTextNode(rawText.slice(cursor, nameStart)));
                const span = document.createElement('span');
                span.setAttribute('data-athr-username-inline', 'true');
                span.textContent = matchedName;
                fragment.appendChild(span);
                usernameSpans.push(span);
                cursor = nameStart + matchedName.length;
                pattern.lastIndex = cursor;
            }
            if (!usernameSpans.length) return;
            if (cursor < rawText.length) fragment.appendChild(document.createTextNode(rawText.slice(cursor)));
            textNode.replaceWith(fragment);
            usernameSpans.forEach(span => {
                if (applyStakeUsernameTarget(span, source)) updated += 1;
            });
        });
        return updated;
    }

    function applyStakeUsernameCustomization(root = document) {
        if (!root || root.nodeType !== 1 && root.nodeType !== 9) return;
        restoreLegacyUsernameMutations();
        const sources = getStakeSourceUsernameCandidates();
        if (!sources.length) return;
        const selector = `${STAKE_USERNAME_PRIMARY_SELECTOR}, ${STAKE_USERNAME_CANDIDATE_SELECTOR}`;
        sources.forEach(configuredSource => {
            applyStakeUsernameAttributes(root, configuredSource);
            const targets = new Set();
            if (root.nodeType === 1 && root.matches?.(selector) && isExactStakeUsernameTarget(root, configuredSource)) targets.add(root);
            root.querySelectorAll?.(selector).forEach(element => {
                if (isExactStakeUsernameTarget(element, configuredSource)) targets.add(element);
            });
            root.querySelectorAll?.('[data-athr-username-target="true"]').forEach(element => {
                if (isSameStakeIdentity(element.getAttribute('data-athr-original-username'), configuredSource)) targets.add(element);
            });
            targets.forEach(element => applyStakeUsernameTarget(element, configuredSource));
            applyStakeUsernameTextNodes(root, configuredSource);
        });
    }

    function installStakeIdentityObserver() {
        if (stakeIdentityObserver || !document.body) return;
        applyStakeUsernameCustomization(document);
        syncATHRStakeVipPreview(document);
        let scheduled = false;
        let vipSyncPending = false;
        const pendingRoots = new Set();
        stakeIdentityObserver = new MutationObserver(mutations => {
            const sourceLowers = getStakeSourceUsernameCandidates().map(source => source.toLocaleLowerCase());
            const containsSource = value => {
                const text = String(value || '').toLocaleLowerCase();
                return sourceLowers.some(source => text.includes(source));
            };
            mutations.forEach(mutation => {
                if (mutation.type === 'characterData' && mutation.target.parentElement) {
                    const parent = mutation.target.parentElement;
                    if (containsSource(mutation.target.nodeValue) || parent.closest?.('[data-athr-username-target="true"], [data-athr-username-attributes]')) pendingRoots.add(parent);
                }
                if (mutation.type === 'attributes' && mutation.target instanceof Element) {
                    const element = mutation.target;
                    const value = element.getAttribute(mutation.attributeName) || '';
                    if (containsSource(value) || element.matches('[data-athr-username-attributes], [data-athr-username-target="true"]')) {
                        pendingRoots.add(element);
                    }
                }
                mutation.addedNodes?.forEach(node => {
                    const element = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement;
                    if (!element) return;
                    const text = String(node.textContent || '').toLocaleLowerCase();
                    if (/monthly bonus|rakeback|weekly boost|unlock vip benefits/u.test(text)) vipSyncPending = true;
                    if (element.closest?.(STAKE_USERNAME_EXCLUSION_SELECTOR)) return;
                    if (containsSource(text) || element.matches?.('[data-athr-username-target="true"], [data-athr-username-attributes]')) pendingRoots.add(element);
                });
            });
            if (!pendingRoots.size && !vipSyncPending) return;
            if (pendingRoots.size > 40) {
                pendingRoots.clear();
                pendingRoots.add(document);
            }
            if (scheduled) return;
            scheduled = true;
            requestAnimationFrame(() => {
                scheduled = false;
                const roots = Array.from(pendingRoots);
                pendingRoots.clear();
                roots.forEach(root => applyStakeUsernameCustomization(root));
                if (vipSyncPending) {
                    vipSyncPending = false;
                    const card = syncATHRStakeVipPreview(document);
                    if (card) refreshATHRVipPreviewUsername(card.querySelector('#athr-vip-name'));
                }
            });
        });
        stakeIdentityObserver.observe(document.body, {
            childList: true,
            subtree: true,
            characterData: true,
            attributes: true,
            attributeFilter: STAKE_USERNAME_ATTRIBUTE_NAMES
        });
    }

    function normalizeTileArray(value) {
        if (!Array.isArray(value)) return [];
        return [...new Set(
            value
                .map(v => Number(v))
                .filter(v => Number.isInteger(v) && v >= 0 && v <= 24)
        )];
    }

    function hashATHRHistorySeed(value) {
        let hash = 2166136261;
        for (const character of String(value || 'athr')) {
            hash ^= character.codePointAt(0);
            hash = Math.imul(hash, 16777619);
        }
        return hash >>> 0;
    }

    function normalizeGridStateSnapshot(value, seed = '') {
        if (!value || typeof value !== 'object') return null;

        const allIndices = Array.from({ length: 25 }, (_, index) => index);
        const revealedTiles = normalizeTileArray(value.revealedTiles);
        let minePositions = normalizeTileArray(value.minePositions);
        const parsedMineCount = Number.parseInt(value.minesCount, 10);
        const minesCount = Number.isInteger(parsedMineCount) && parsedMineCount >= 1 && parsedMineCount <= 24
            ? parsedMineCount
            : Math.min(24, Math.max(0, minePositions.length));

        // v5.7.2 originally stored inline SVG bombs as gems because it looked
        // only for a background-image URL. Repair those legacy snapshots using
        // the saved mine count, never placing a repaired bomb on a clicked gem.
        if (minesCount > minePositions.length) {
            const occupied = new Set(minePositions);
            const revealed = new Set(revealedTiles);
            let candidates = allIndices.filter(index => !occupied.has(index) && !revealed.has(index));
            if (candidates.length) {
                const offset = hashATHRHistorySeed(seed) % candidates.length;
                candidates = candidates.slice(offset).concat(candidates.slice(0, offset));
                minePositions = minePositions.concat(candidates.slice(0, minesCount - minePositions.length));
            }
        }

        const mineSet = new Set(minePositions.slice(0, minesCount || minePositions.length));
        const gemPositions = allIndices.filter(index => !mineSet.has(index));
        return {
            gemPositions,
            minePositions: Array.from(mineSet),
            // A revealed index can be the clicked bomb in a losing preview.
            revealedTiles,
            minesCount: minesCount || mineSet.size
        };
    }

    function persistLocationSettings() {
        settings.customBombLocations = customBombLocations ? Array.from(customBombLocations) : [];
        settings.customGemLocations = customGemLocations ? Array.from(customGemLocations) : [];
        persistSettings();
    }

    function normalizeHistoryNumber(value) {
        const parsed = Number(value);
        return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
    }

    function roundHistoryMoney(value) {
        const amount = normalizeHistoryNumber(value);
        return Math.round((amount + Number.EPSILON) * 100000000) / 100000000;
    }

    function normalizeBetHistoryEntry(entry) {
        if (!entry || typeof entry !== 'object') return null;
        const currency = ensureCurrencyRegistered(entry.currency);
        if (!currency) return null;

        const betAmount = roundHistoryMoney(entry.betAmount);
        const multiplier = normalizeHistoryNumber(entry.multiplier);
        // Freeze the payout supplied by the completed round. Re-deriving it
        // later can select a live wallet value or a newer multiplier after a
        // Stake rerender, which is what made the modal show the full balance.
        const suppliedPayout = roundHistoryMoney(entry.payout);
        const payout = suppliedPayout > 0
            ? suppliedPayout
            : (multiplier > 0 && betAmount > 0 ? roundHistoryMoney(betAmount * multiplier) : 0);

        const betId = entry.betId ? String(entry.betId) : '';
        const gridState = normalizeGridStateSnapshot(
            entry.gridState,
            `${betId}:${entry.time || ''}:${entry.date || ''}:${currency}:${betAmount}`
        );

        return {
            snapshotVersion: BET_HISTORY_SCHEMA_VERSION,
            betAmount,
            multiplier,
            payout,
            currency,
            time: typeof entry.time === 'string' && entry.time.trim() ? entry.time : null,
            date: typeof entry.date === 'string' && entry.date.trim() ? entry.date : null,
            betId,
            gridState
        };
    }

    function loadStoredBetHistory() {
        try {
            const stored = localStorage.getItem(BET_HISTORY_KEY);
            if (!stored) return [];
            const parsed = JSON.parse(stored);
            if (Array.isArray(parsed)) {
                const sourceEntries = parsed.slice(0, 10);
                const repairedEntries = sourceEntries.map(normalizeBetHistoryEntry).filter(Boolean);
                if (JSON.stringify(sourceEntries) !== JSON.stringify(repairedEntries)) {
                    localStorage.setItem(BET_HISTORY_KEY, JSON.stringify(repairedEntries));
                    console.info('[ATHR] Repaired legacy bet-history snapshots.');
                }
                return repairedEntries;
            }
        } catch (error) {
            console.warn('Bet history load error:', error);
        }
        return [];
    }

    let startupAttemptPromise = null;
    async function init() {
        if (window.fakeMinesScriptActive === true) {
            ensureATHRUIMounted();
            return true;
        }
        if (startupAttemptPromise) return startupAttemptPromise;

        startupAttemptPromise = Promise.resolve().then(() => {
            const started = startScript();
            if (started) {
                return true;
            }
            console.error('[ATHR] UI could not be mounted.');
            return false;
        }).catch(error => {
            console.error('[ATHR] Startup error:', error);
            return false;
        });

        try {
            return await startupAttemptPromise;
        } finally {
            startupAttemptPromise = null;
        }
    }

    function getDisplayAmountMode() {
        const mode = String(settings.displayAmountMode || 'USD').toUpperCase();
        return ['USD', 'LOCAL', 'CRYPTO'].includes(mode) ? mode : 'USD';
    }

    function getLocalCurrencyCode() {
        const code = String(settings.localCurrencyCode || 'INR').trim().toUpperCase();
        return /^[A-Z]{2,6}$/.test(code) ? code : 'INR';
    }

    function getLocalCurrencySymbol() {
        const symbol = String(settings.localCurrencySymbol || '').replace(/[<>&"'`]/g, '').trim().slice(0, 6);
        return symbol || getLocalCurrencyCode();
    }

    function loadStakeFiatRateCache() {
        const rates = { USD: 1 };
        const updatedAt = { USD: Date.now() };
        try {
            const payload = JSON.parse(localStorage.getItem(FIAT_RATE_CACHE_KEY) || '{}');
            const storedRates = payload?.rates && typeof payload.rates === 'object' ? payload.rates : payload;
            const storedTimes = payload?.updatedAt && typeof payload.updatedAt === 'object' ? payload.updatedAt : {};
            if (storedRates && typeof storedRates === 'object') {
                Object.entries(storedRates).forEach(([currency, value]) => {
                    const code = String(currency || '').trim().toUpperCase();
                    const rate = Number(value);
                    if (/^[A-Z]{3}$/.test(code) && Number.isFinite(rate) && rate > 0) rates[code] = rate;
                });
            }
            Object.entries(storedTimes).forEach(([currency, value]) => {
                const code = String(currency || '').trim().toUpperCase();
                const timestamp = Number(value);
                if (/^[A-Z]{3}$/.test(code) && Number.isFinite(timestamp) && timestamp > 0) updatedAt[code] = timestamp;
            });
        } catch (error) {
            console.warn('[ATHR CURRENCY] Fiat-rate cache could not be read:', error);
        }
        const savedCode = String(settings?.localCurrencyRateCode || settings?.localCurrencyCode || '').trim().toUpperCase();
        const savedRate = Number(settings?.localCurrencyRate);
        if (/^[A-Z]{3}$/.test(savedCode) && Number.isFinite(savedRate) && savedRate > 0) rates[savedCode] = savedRate;
        loadStakeFiatRateCache.updatedAt = updatedAt;
        return rates;
    }

    function saveStakeFiatRateCache() {
        try {
            localStorage.setItem(FIAT_RATE_CACHE_KEY, JSON.stringify({
                rates: stakeFiatRates,
                updatedAt: stakeFiatRateUpdatedAt
            }));
        } catch (error) {
            console.warn('[ATHR CURRENCY] Fiat-rate cache could not be saved:', error);
        }
    }

    function getEffectiveFiatRate(currency = getLocalCurrencyCode()) {
        const code = String(currency || '').trim().toUpperCase();
        if (code === 'USD') return 1;
        const settingsCode = String(settings.localCurrencyRateCode || '').trim().toUpperCase();
        const settingsRate = Number(settings.localCurrencyRate);
        if (settingsCode === code && Number.isFinite(settingsRate) && settingsRate > 0) return settingsRate;
        const cachedRate = Number(stakeFiatRates?.[code]);
        return Number.isFinite(cachedRate) && cachedRate > 0 ? cachedRate : 0;
    }

    function isStakeFiatRateReady() {
        return getDisplayAmountMode() !== 'LOCAL' || getEffectiveFiatRate() > 0;
    }

    function getStakeDisplayCurrencyCode(currency = activeGameCurrency) {
        const mode = getDisplayAmountMode();
        if (mode === 'CRYPTO') return normalizeCurrency(currency);
        return mode === 'LOCAL' ? getLocalCurrencyCode() : 'USD';
    }

    function getStakeDisplaySyncLabel(currency = activeGameCurrency) {
        const displayCode = getStakeDisplayCurrencyCode(currency);
        if (getDisplayAmountMode() === 'CRYPTO') return `${displayCode} native`;
        return `${getFiatFlagEmoji(displayCode)} ${displayCode} fiat`;
    }

    function getFiatCurrencySymbol(currency) {
        const code = String(currency || '').trim().toUpperCase();
        if (!/^[A-Z]{3}$/.test(code)) return code;
        try {
            const part = new Intl.NumberFormat('en-US', {
                style: 'currency',
                currency: code,
                currencyDisplay: 'narrowSymbol'
            }).formatToParts(0).find(item => item.type === 'currency');
            return String(part?.value || code).slice(0, 6);
        } catch (error) {
            return code;
        }
    }

    function formatUsdAmount(amount) {
        const value = Number(amount);
        const safeValue = Number.isFinite(value) ? value : 0;
        const sign = safeValue < 0 ? '-' : '';
        return `${sign}$${Math.abs(safeValue).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    }

    function formatNativeFiatConversion(amountUsd) {
        const value = Number(amountUsd);
        const usdValue = Number.isFinite(value) ? value : 0;
        const fiatCode = getLocalCurrencyCode();
        if (fiatCode === 'USD') return formatUsdAmount(usdValue);

        const rate = getEffectiveFiatRate(fiatCode);
        if (!(rate > 0)) {
            void ensureStakeFiatRate(fiatCode);
            return `${getLocalCurrencySymbol()}\u2026`;
        }

        const converted = usdValue * rate;
        const sign = converted < 0 ? '-' : '';
        return `${sign}${getLocalCurrencySymbol()}${Math.abs(converted).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    }

    // Format every ATHR fiat-value slot using the user's chosen display layer.
    // Stored balances and payout math remain in USD, so changing the view never
    // changes a wallet balance or an active bet.
    function formatBalance(amount, currency = selectedBalanceCurrency) {
        const value = Number(amount);
        const usdValue = Number.isFinite(value) ? value : 0;
        const mode = getDisplayAmountMode();

        if (mode === 'LOCAL') {
            const rate = getEffectiveFiatRate();
            if (!(rate > 0)) return `${getLocalCurrencySymbol()}\u2026`;
            const converted = usdValue * rate;
            const sign = converted < 0 ? '-' : '';
            return `${sign}${getLocalCurrencySymbol()}${Math.abs(converted).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
        }

        if (mode === 'CRYPTO') {
            return formatCryptoDisplayAmount(usdValue, ensureCurrencyRegistered(currency) || activeGameCurrency);
        }

        return formatUsdAmount(usdValue);
    }

    function getBalanceInputUnitLabel(currency = selectedBalanceCurrency) {
        const mode = getDisplayAmountMode();
        if (mode === 'LOCAL') return getLocalCurrencyCode();
        if (mode === 'CRYPTO') return normalizeCurrency(currency);
        return 'USD';
    }

    function usdToDisplayInputValue(usdAmount, currency = selectedBalanceCurrency) {
        const value = Number(usdAmount);
        const safeValue = Number.isFinite(value) ? value : 0;
        const mode = getDisplayAmountMode();
        if (mode === 'LOCAL') {
            const rate = getEffectiveFiatRate();
            return rate > 0 ? safeValue * rate : 0;
        }
        if (mode === 'CRYPTO') {
            const code = normalizeCurrency(currency);
            const rate = Number(CRYPTO_RATES[code]) || Number(CRYPTO_RATE_DEFAULTS[code]) || 1;
            return safeValue / rate;
        }
        return safeValue;
    }

    function displayInputValueToUsd(displayAmount, currency = selectedBalanceCurrency) {
        const value = Number(displayAmount);
        const safeValue = Number.isFinite(value) ? value : 0;
        const mode = getDisplayAmountMode();
        if (mode === 'LOCAL') {
            const rate = getEffectiveFiatRate();
            return rate > 0 ? safeValue / rate : 0;
        }
        if (mode === 'CRYPTO') {
            const code = normalizeCurrency(currency);
            const rate = Number(CRYPTO_RATES[code]) || Number(CRYPTO_RATE_DEFAULTS[code]) || 1;
            return safeValue * rate;
        }
        return safeValue;
    }

    // Stake's bet input uses whichever display unit is selected in Wallet
    // Settings. Convert that visible value once and keep all game math in USD.
    function getBetInputUsdValue(input = document.querySelector(FAKE_INPUT_SELECTOR), currency = getBetSessionCurrency()) {
        if (activeBetSession && Number.isFinite(Number(activeBetSession.betAmount))) {
            return Math.max(0, Number(activeBetSession.betAmount));
        }
        const displayValue = Number.parseFloat(input?.value || '0');
        return Math.max(0, displayInputValueToUsd(Number.isFinite(displayValue) ? displayValue : 0, currency));
    }

    function getBalanceInputPrecision(currency = selectedBalanceCurrency) {
        if (getDisplayAmountMode() !== 'CRYPTO') return 2;
        void currency;
        return 8;
    }

    function formatDisplayInputNumber(value, currency = selectedBalanceCurrency) {
        const numericValue = Number(value);
        const safeValue = Number.isFinite(numericValue) ? numericValue : 0;
        const precision = getBalanceInputPrecision(currency);
        if (getDisplayAmountMode() === 'CRYPTO' && Math.abs(safeValue) < 0.5 * (10 ** -precision)) {
            return (0).toFixed(precision);
        }
        return safeValue.toFixed(precision);
    }

    function formatNativeCryptoValue(nativeValue, currency, precisionOverride = null) {
        const code = normalizeCurrency(currency);
        const meta = CRYPTO_CURRENCIES[code] || CRYPTO_CURRENCIES[DEFAULT_CURRENCY];
        const precision = precisionOverride === null
            ? Math.min(8, Math.max(0, Number(meta?.precision) || 8))
            : Math.min(8, Math.max(0, Number(precisionOverride) || 0));
        const value = Number(nativeValue);
        if (!Number.isFinite(value) || Object.is(value, -0) || value === 0) return '0';
        const fixed = value.toFixed(precision);
        return fixed.includes('.')
            ? fixed.replace(/(\.\d*?[1-9])0+$/u, '$1').replace(/\.0+$/u, '')
            : fixed;
    }

    // Stake keeps native crypto amounts at eight fractional digits when fiat
    // display is disabled (for example, 0.00000000 USDT). Keep this
    // presentation formatter separate from formatCrypto(), whose compact value
    // is also used by conversion and calculation code.
    function formatCryptoDisplayAmount(usdValue, currency = activeGameCurrency) {
        const code = normalizeCurrency(currency);
        const precision = 8;
        const rate = Number(CRYPTO_RATES[code]) || Number(CRYPTO_RATE_DEFAULTS[code]) || 1;
        const value = Number(usdValue);
        const nativeValue = Number.isFinite(value) ? value / rate : 0;
        const zeroThreshold = 0.5 * (10 ** -precision);
        const displayValue = Math.abs(nativeValue) < zeroThreshold ? 0 : nativeValue;
        return displayValue.toFixed(precision);
    }

    // Synchronize the existing native popup; never mount a second amount popup.
    const athrMoneySnapshots = new WeakMap();
    let athrAmountTrigger = null;

    function getATHRAmountOwner(element) {
        const cell = element?.closest?.('tr[data-bet-index] [data-athr-money-cell="true"]');
        if (cell && athrMoneySnapshots.has(cell)) return cell;
        const button = element?.closest?.('button, [role="button"]');
        if (!button || button.closest('table, [role="dialog"], [data-modal-card="true"], #balance-ui')) return null;
        // Captured Stake header uses coin-toggle. coin-toggle-currency-* are
        // usually menu choices and must not become the tooltip's balance owner.
        return button === getActiveCurrencyButton() ? button : null;
    }

    function isATHRTooltipNearOwner(host, owner) {
        if (!host?.isConnected || !owner?.isConnected) return false;
        const a = owner.getBoundingClientRect(), b = host.getBoundingClientRect();
        return a.width > 0 && a.height > 0 && b.width > 0 && b.height > 0 && b.height < 110
            && b.right >= a.left - 12 && b.left <= a.right + 12
            && b.bottom >= a.top - 28 && b.top <= a.bottom + 28;
    }

    function getATHRTooltipSnapshot(host, content, preferredCurrency) {
        let owner = getATHRAmountOwner(content);
        if (!owner && host.id) {
            for (const trigger of document.querySelectorAll('[aria-describedby]')) {
                if ((trigger.getAttribute('aria-describedby') || '').split(/\s+/).includes(host.id)) {
                    owner = getATHRAmountOwner(trigger);
                    if (owner) break;
                }
            }
        }
        if (!owner && isATHRTooltipNearOwner(host, athrAmountTrigger)) owner = athrAmountTrigger;
        if (!owner && !host.closest('table, [data-fake-bet-modal="true"]')) {
            const header = getActiveCurrencyButton();
            // Restore an already-open header popup too, including when Stake
            // mounts it without ARIA and before our pointer listeners attach.
            if (isATHRTooltipNearOwner(host, header)) owner = header;
        }
        if (!owner) return null;
        const snapshot = athrMoneySnapshots.get(owner);
        if (snapshot) return snapshot;
        if (!settings.enableFakeBalance) return null;
        const code = ensureCurrencyRegistered(preferredCurrency) || activeGameCurrency;
        return { code, usdValue: getCryptoBalance(code) };
    }

    function bindATHRHistoryMoneyCell(cell, usdValue, currency) {
        if (!cell) return;
        const code = ensureCurrencyRegistered(currency) || DEFAULT_CURRENCY;
        athrMoneySnapshots.set(cell, { code, usdValue: Number(usdValue) || 0 });
    }

    for (const type of ['pointerover', 'focusin', 'pointerdown']) {
        document.addEventListener(type, event => {
            if (event.target?.closest?.('[role="tooltip"], .tooltip-content')) return;
            athrAmountTrigger = getATHRAmountOwner(event.target);
            if (athrAmountTrigger) scheduleATHRWiringSync('native-amount-tooltip', 40);
        }, true);
    }
    // Remove an obsolete popup from a replaced build, without touching native UI.
    document.getElementById('athr-bet-amount-tip')?.remove();

    const ATHR_NATIVE_CRYPTO_TOOLTIP_CONTENT_SELECTOR = [
        '[role="tooltip"] .tooltip-content',
        '.tooltip:not(.tooltip-wrapper) > .tooltip-content',
        '.tooltip-content'
    ].join(',');

    function isATHRLongZeroCryptoAmount(value) {
        return /^[+-]?0\.0{4,}$/u.test(String(value ?? '').trim());
    }

    function getATHRNativeCryptoTooltipHost(content) {
        if (!content) return null;
        return content.closest?.('[role="tooltip"], .tooltip') || content;
    }

    function isATHRZeroHeaderCryptoTooltip(content) {
        if (!content?.matches?.('.tooltip-content')) return false;
        const wrapper = Array.from(content.children || []).find(child => child.matches?.('.fiat-wrapper')) || null;
        if (!wrapper || content.children.length !== 1) return false;
        const amount = wrapper.querySelector('span[data-ds-text="true"]');
        const icon = wrapper.querySelector('svg[data-ds-icon], [data-testid="currency-icon-skeleton"]');
        if (!amount || !icon || !getATHRNativeCryptoTooltipHost(content)) return false;
        const code = ensureCurrencyRegistered(icon.getAttribute?.('data-athr-icon-rendered'))
            || ensureCurrencyRegistered(icon.getAttribute?.('data-ds-icon'))
            || ensureCurrencyRegistered(icon.closest?.('span[title]')?.getAttribute('title'))
            || activeGameCurrency;
        return getCryptoBalance(code) === 0 || isATHRLongZeroCryptoAmount(amount.textContent);
    }

    function syncATHRHeaderCryptoTooltips(root = document, preferredCurrency = activeGameCurrency) {
        if (!root?.querySelectorAll) return 0;
        const contents = new Set();
        if (root.nodeType === Node.ELEMENT_NODE && root.matches?.(ATHR_NATIVE_CRYPTO_TOOLTIP_CONTENT_SELECTOR)) {
            contents.add(root);
        }
        root.querySelectorAll(ATHR_NATIVE_CRYPTO_TOOLTIP_CONTENT_SELECTOR).forEach(content => contents.add(content));

        let updated = 0;
        contents.forEach(content => {
            const wrapper = Array.from(content.children || []).find(child => child.matches?.('.fiat-wrapper')) || null;
            if (!wrapper || content.children.length !== 1) return;
            const host = getATHRNativeCryptoTooltipHost(content);
            const amount = wrapper.querySelector('span[data-ds-text="true"]');
            const icon = wrapper.querySelector('svg[data-ds-icon]');
            if (!host || !amount || !icon) return;

            const snapshot = getATHRTooltipSnapshot(host, content, preferredCurrency);
            if (!snapshot) return;
            const code = snapshot.code;
            const nativeText = formatCryptoDisplayAmount(snapshot.usdValue, code);
            if (amount.textContent !== nativeText) amount.textContent = nativeText;
            applyCurrencyIcon(icon, code);
            const titleHost = icon.closest?.('span[title]');
            if (titleHost) {
                titleHost.setAttribute('title', code.toLowerCase());
                titleHost.setAttribute('aria-label', `${CRYPTO_CURRENCIES[code].name} (${code})`);
            }
            wrapper.setAttribute('data-athr-tooltip-currency', code);
            updated += 1;
        });
        return updated;
    }

    // Compatibility shim for older wiring. A zero-value native tooltip is
    // valid Stake UI and must stay mounted.
    function suppressATHRZeroHeaderCryptoTooltips(root = document) {
        void root;
        return 0;
    }

    // Kept as the stable call site used by the wiring observer.
    function normalizeATHRNativeCryptoZero(root = document) {
        return syncATHRHeaderCryptoTooltips(root, activeGameCurrency);
    }

    function formatCrypto(usdValue, currency = activeGameCurrency) {
        const code = normalizeCurrency(currency);
        const rate = Number(CRYPTO_RATES[code]) || Number(CRYPTO_RATE_DEFAULTS[code]) || 1;
        const value = Number(usdValue);
        const nativeValue = Number.isFinite(value) ? value / rate : 0;
        return formatNativeCryptoValue(nativeValue, code);
    }

    function formatCashoutCrypto(usdValue, currency = getBetSessionCurrency()) {
        return formatCryptoDisplayAmount(usdValue, currency);
    }

    function formatCashoutDisplay(usdValue, currency = getBetSessionCurrency()) {
        return getDisplayAmountMode() === 'CRYPTO'
            ? formatCashoutCrypto(usdValue, currency)
            : formatBalance(usdValue, currency);
    }

    let stakeFiatRateRequestToken = 0;
    let pendingStakeFiatCode = null;
    let pendingStakeDisplayBetUsd = null;
    const stakeFiatRateRequests = new Map();

    function captureBetInputUsdBeforeDisplayChange() {
        if (activeBetSession) return null;
        const input = document.querySelector(FAKE_INPUT_SELECTOR);
        const displayValue = Number.parseFloat(input?.value || '');
        if (!Number.isFinite(displayValue)) return null;
        const usdValue = displayInputValueToUsd(displayValue, activeGameCurrency);
        if (Number.isFinite(usdValue) && usdValue >= 0) {
            athrWiringState.lastInputUsd = usdValue;
            return usdValue;
        }
        return null;
    }

    function reconcileBetInputWithStakeDisplay() {
        if (pendingStakeDisplayBetUsd === null || activeBetSession) return;
        if (getDisplayAmountMode() === 'LOCAL' && !isStakeFiatRateReady()) return;
        const input = document.querySelector(FAKE_INPUT_SELECTOR);
        if (!input) return;
        const displayValue = usdToDisplayInputValue(pendingStakeDisplayBetUsd, activeGameCurrency);
        input.value = formatDisplayInputNumber(displayValue, activeGameCurrency);
        athrWiringState.lastInputUsd = pendingStakeDisplayBetUsd;
        pendingStakeDisplayBetUsd = null;
        input.dispatchEvent(new Event('input', { bubbles: true }));
    }

    function refreshDisplayCurrencyViews() {
        reconcileBetInputWithStakeDisplay();
        updateBalanceUI();
        updateCurrencyConversion();
        updateStatsDisplay();
        syncGameCurrencyAdornments();
        refreshHeaderWalletPanel();
        updateBetHistoryTable();
        if (settings.enableFakeWithdrawals) updateWithdrawalHistoryTable();
        if (settings.enableFakeDeposits) updateDepositHistoryTable();
        const openBetModal = document.querySelector('[data-fake-bet-modal="true"][data-athr-bet-index]');
        const openBetIndex = Number.parseInt(openBetModal?.getAttribute('data-athr-bet-index') || '', 10);
        if (openBetModal && Number.isInteger(openBetIndex) && betHistory[openBetIndex]) {
            refreshBetModalMoneyValues(openBetModal, betHistory[openBetIndex]);
        }
    }

    async function refreshStakeFiatRate(currency) {
        const code = String(currency || '').trim().toUpperCase();
        if (!/^[A-Z]{3}$/.test(code)) return false;
        const token = ++stakeFiatRateRequestToken;

        if (code === 'USD') {
            settings.localCurrencyRate = 1;
            settings.localCurrencyRateCode = 'USD';
            stakeFiatRates.USD = 1;
            stakeFiatRateUpdatedAt.USD = Date.now();
            saveStakeFiatRateCache();
            persistSettings();
            refreshDisplayCurrencyViews();
            return true;
        }

        const cachedRate = Number(stakeFiatRates[code]);
        const cachedAt = Number(stakeFiatRateUpdatedAt[code]);
        if (cachedRate > 0 && cachedAt > 0 && Date.now() - cachedAt < FIAT_RATE_CACHE_MAX_AGE_MS) {
            settings.localCurrencyRate = cachedRate;
            settings.localCurrencyRateCode = code;
            persistSettings();
            refreshDisplayCurrencyViews();
            return true;
        }

        try {
            let rate = 0;
            try {
                const response = await fetch(`https://api.frankfurter.dev/v2/rate/USD/${encodeURIComponent(code)}`, { cache: 'no-store' });
                if (response.ok) {
                    const data = await response.json();
                    rate = Number(data?.rate);
                }
            } catch (error) {
                console.debug(`[ATHR CURRENCY] Frankfurter ${code} rate unavailable:`, error);
            }

            // CoinGecko's supported USDT cross-rate remains a fallback for fiat
            // codes that do not currently have a Frankfurter quote.
            if (!(rate > 0)) {
                const fiatKey = code.toLowerCase();
                const response = await fetch(`https://api.coingecko.com/api/v3/simple/price?ids=tether&vs_currencies=usd,${encodeURIComponent(fiatKey)}`, { cache: 'no-store' });
                if (response.ok) {
                    const data = await response.json();
                    const usdtUsd = Number(data?.tether?.usd);
                    const usdtFiat = Number(data?.tether?.[fiatKey]);
                    rate = usdtUsd > 0 && usdtFiat > 0 ? usdtFiat / usdtUsd : 0;
                }
            }
            if (token !== stakeFiatRateRequestToken || getLocalCurrencyCode() !== code || !(rate > 0)) return false;

            settings.localCurrencyRate = rate;
            settings.localCurrencyRateCode = code;
            stakeFiatRates[code] = rate;
            stakeFiatRateUpdatedAt[code] = Date.now();
            saveStakeFiatRateCache();
            persistSettings();
            refreshDisplayCurrencyViews();
            return true;
        } catch (error) {
            console.warn(`[ATHR CURRENCY] Could not refresh ${code} display rate:`, error);
            return false;
        }
    }

    function ensureStakeFiatRate(currency = getLocalCurrencyCode()) {
        const code = String(currency || '').trim().toUpperCase();
        if (!/^[A-Z]{3}$/.test(code)) return Promise.resolve(false);
        if (code === 'USD' || getEffectiveFiatRate(code) > 0) return Promise.resolve(true);
        if (stakeFiatRateRequests.has(code)) return stakeFiatRateRequests.get(code);
        const request = refreshStakeFiatRate(code).finally(() => stakeFiatRateRequests.delete(code));
        stakeFiatRateRequests.set(code, request);
        return request;
    }

    function getStakeWalletControlState(control) {
        if (!control) return null;
        const nestedControl = !control.matches?.('input[type="checkbox"], [role="switch"]')
            ? control.querySelector?.('input[type="checkbox"], [role="switch"]')
            : null;
        if (nestedControl && nestedControl !== control) {
            const nestedState = getStakeWalletControlState(nestedControl);
            if (nestedState !== null) return nestedState;
        }
        if ('checked' in control) return !!control.checked;
        const ariaChecked = String(control.getAttribute('aria-checked') || '').toLowerCase();
        if (ariaChecked === 'true' || ariaChecked === 'false') return ariaChecked === 'true';
        const ariaPressed = String(control.getAttribute('aria-pressed') || '').toLowerCase();
        if (ariaPressed === 'true' || ariaPressed === 'false') return ariaPressed === 'true';
        const dataState = String(control.getAttribute('data-state') || '').toLowerCase();
        if (dataState === 'checked' || dataState === 'on' || dataState === 'active') return true;
        if (dataState === 'unchecked' || dataState === 'off' || dataState === 'inactive') return false;
        const dataChecked = String(control.getAttribute('data-checked') || '').toLowerCase();
        if (dataChecked === 'true' || dataChecked === 'false') return dataChecked === 'true';
        const className = String(control.className || '');
        if (/(?:^|\s)(?:is-)?(?:checked|active|on)(?:\s|$)/i.test(className)) return true;
        if (/(?:^|\s)(?:is-)?(?:unchecked|inactive|off)(?:\s|$)/i.test(className)) return false;
        return null;
    }

    function findStakeFiatDisplaySwitch(walletDialog) {
        const controls = Array.from(walletDialog.querySelectorAll([
            'input[type="checkbox"]',
            '[role="switch"]',
            '.fiat-toggle button[aria-pressed]',
            '.fiat-toggle button[data-state]',
            '.fiat-toggle[data-state]',
            '[data-testid*="fiat" i][aria-checked]',
            '[data-testid*="fiat" i][data-state]'
        ].join(',')));
        return controls.find(control => {
            const directLabel = `${control.value || ''} ${control.getAttribute('aria-label') || ''}`;
            if (/display\s+crypto\s+in\s+fiat/i.test(directLabel)) return true;
            if (control.closest?.('.fiat-toggle, [data-testid*="fiat" i]')) return true;
            let parent = control.parentElement;
            for (let depth = 0; parent && parent !== walletDialog && depth < 5; depth += 1, parent = parent.parentElement) {
                const text = String(parent.textContent || '').trim();
                if (text.length <= 180 && /display\s+crypto\s+in\s+fiat/i.test(text)) return true;
            }
            return false;
        }) || null;
    }

    function getFiatCodeFromControl(control) {
        if (!control) return null;
        const option = control.closest?.('label, [role="radio"], button, [data-currency], [data-currency-code]') || control.parentElement;
        const candidates = [
            control.value,
            control.getAttribute?.('data-currency'),
            control.getAttribute?.('data-currency-code'),
            control.getAttribute?.('aria-label'),
            control.getAttribute?.('data-testid'),
            option?.getAttribute?.('data-currency'),
            option?.getAttribute?.('data-currency-code'),
            option?.getAttribute?.('aria-label'),
            option?.getAttribute?.('data-testid'),
            option?.textContent
        ];
        const excluded = new Set(['ATH', 'VIP', 'FIAT', 'CRY', 'ALL', 'BET', 'USD']);
        for (const candidate of candidates) {
            const text = String(candidate || '').trim().toUpperCase();
            if (text === 'USD') return 'USD';
            const tokens = text.match(/\b[A-Z]{3}\b/g) || [];
            const code = tokens.find(token => token === 'USD' || (!excluded.has(token) && !SUPPORTED_CURRENCY_SET.has(token)));
            if (code) return code;
        }
        return null;
    }

    function getStakeSelectedFiatCode(walletDialog) {
        const displaySwitch = findStakeFiatDisplaySwitch(walletDialog);
        const selectedControls = new Set(Array.from(walletDialog.querySelectorAll([
            'input[type="radio"]:checked',
            '[role="radio"][aria-checked="true"]',
            '[role="radio"][data-state="checked"]',
            '[role="option"][aria-selected="true"]',
            'button[aria-selected="true"]',
            'button[aria-pressed="true"]',
            'button[data-state="checked"]',
            'button[data-state="active"]',
            '.wallet-currency-dropdown .button.selected',
            '.wallet-currency-dropdown .button.is-selected',
            '.wallet-currency-dropdown .button.active',
            'select option:checked'
        ].join(','))));
        walletDialog.querySelectorAll('select').forEach(select => {
            if (select.selectedOptions?.[0]) selectedControls.add(select.selectedOptions[0]);
        });

        const ranked = Array.from(selectedControls).map(control => {
            if (control === displaySwitch || control.contains?.(displaySwitch) || displaySwitch?.contains?.(control)) return null;
            const code = getFiatCodeFromControl(control);
            if (!code) return null;
            let score = 0;
            let parent = control;
            for (let depth = 0; parent && parent !== walletDialog && depth < 6; depth += 1, parent = parent.parentElement) {
                const text = String(parent.textContent || '').trim();
                if (/fiat\s+currency|currency\s+display|display\s+currency/i.test(text)) score += 80 - depth * 5;
                if (/display\s+crypto\s+in\s+fiat/i.test(text)) score += 25;
            }
            if (Object.prototype.hasOwnProperty.call(FIAT_COUNTRY_CODES, code)) score += 30;
            if (control.matches?.('[aria-selected="true"], [aria-checked="true"], [aria-pressed="true"], [data-state="checked"], [data-state="active"], option:checked')) score += 40;
            return { code, score };
        }).filter(Boolean).sort((a, b) => b.score - a.score);
        return ranked[0]?.code || pendingStakeFiatCode || null;
    }

    function syncDisplayModeFromStakeWalletSettings(root = document) {
        const dialogs = Array.from(root.querySelectorAll?.('[role="dialog"], [data-testid*="modal"], [data-modal-card="true"]') || []);
        const walletDialog = dialogs.find(dialog => {
            const text = String(dialog.textContent || '');
            return /display\s+crypto\s+in\s+fiat/i.test(text)
                && (/\bwallet\b/i.test(text) || /\bsettings\b/i.test(text));
        });
        if (!walletDialog) return false;

        const displaySwitch = findStakeFiatDisplaySwitch(walletDialog);
        const fiatEnabled = getStakeWalletControlState(displaySwitch);
        if (fiatEnabled === null) return false;
        if (fiatEnabled === false) {
            pendingStakeFiatCode = null;
            if (settings.displayAmountMode === 'CRYPTO') return false;
            const previousBetUsd = captureBetInputUsdBeforeDisplayChange();
            settings.displayAmountMode = 'CRYPTO';
            if (previousBetUsd !== null) pendingStakeDisplayBetUsd = previousBetUsd;
            persistSettings();
            refreshDisplayCurrencyViews();
            return true;
        }

        const fiatCode = getStakeSelectedFiatCode(walletDialog) || getLocalCurrencyCode() || 'USD';
        if (!fiatCode) return false;
        const nextMode = fiatCode === 'USD' ? 'USD' : 'LOCAL';
        const previousCode = getLocalCurrencyCode();
        const cachedRate = Number(stakeFiatRates[fiatCode]);
        const rateMatches = String(settings.localCurrencyRateCode || previousCode).toUpperCase() === fiatCode
            && Number(settings.localCurrencyRate) > 0;
        const changed = settings.displayAmountMode !== nextMode || previousCode !== fiatCode;
        const previousBetUsd = changed ? captureBetInputUsdBeforeDisplayChange() : null;

        settings.displayAmountMode = nextMode;
        settings.localCurrencyCode = fiatCode;
        settings.localCurrencySymbol = getFiatCurrencySymbol(fiatCode);
        pendingStakeFiatCode = null;
        if (fiatCode === 'USD') {
            settings.localCurrencyRate = 1;
            settings.localCurrencyRateCode = 'USD';
        } else if (Number.isFinite(cachedRate) && cachedRate > 0) {
            settings.localCurrencyRate = cachedRate;
            settings.localCurrencyRateCode = fiatCode;
        } else if (!rateMatches) {
            settings.localCurrencyRate = 0;
            settings.localCurrencyRateCode = fiatCode;
        }
        persistSettings();
        if (previousBetUsd !== null) pendingStakeDisplayBetUsd = previousBetUsd;
        if (changed) refreshDisplayCurrencyViews();
        if (fiatCode !== 'USD') void refreshStakeFiatRate(fiatCode);
        return changed;
    }

    let stakeWalletDisplayObserver = null;

    function scheduleATHRWiringSync(reason = 'dom', followupDelay = 0) {
        athrWiringState.reasons.add(reason);
        if (!athrWiringState.frame) {
            athrWiringState.frame = requestAnimationFrame(() => {
                athrWiringState.frame = 0;
                reconcileATHRWiring();
            });
        }
        if (followupDelay > 0) {
            clearTimeout(athrWiringState.followupTimer);
            athrWiringState.followupTimer = setTimeout(() => {
                scheduleATHRWiringSync(`${reason}:settled`);
            }, followupDelay);
        }
    }

    function isATHRWiringMutationRelevant(mutation) {
        const target = mutation.target?.nodeType === 1 ? mutation.target : mutation.target?.parentElement;
        if (target?.closest?.('#balance-ui')) return false;
        if (mutation.type === 'attributes') {
            return !!target?.matches?.(
                'input[type="radio"], input[type="checkbox"], [role="radio"], [role="switch"], [role="tooltip"], .tooltip-content, button[data-testid^="coin-toggle-currency-"], input[data-testid="input-game-amount"], [data-testid="modal-wallet"], .currencies-item, .game-result-wrap'
            ) || !!target?.closest?.('[role="dialog"], [role="listbox"], [role="menu"], [role="tooltip"], .game-result-wrap');
        }
        if (mutation.type === 'characterData') {
            return !!target?.closest?.(
                'button[data-testid^="coin-toggle-currency-"], [data-athr-active-currency], [data-testid="modal-wallet"], [role="dialog"], [role="tooltip"], .tooltip-content, .game-result-wrap'
            );
        }
        const selector = [
            'button[data-testid^="coin-toggle-currency-"]',
            '[role="dialog"]',
            '[role="listbox"]',
            '[role="menu"]',
            '[role="tooltip"]',
            '.tooltip-content',
            '[data-testid="modal-wallet"]',
            '.currencies',
            '.currencies-item',
            'input[data-testid="input-game-amount"]',
            '#fake-bet-input',
            '.game-result-wrap'
        ].join(',');
        return Array.from(mutation.addedNodes || []).some(node =>
            node.nodeType === 1 && (node.matches?.(selector) || node.querySelector?.(selector))
        ) || Array.from(mutation.removedNodes || []).some(node =>
            node.nodeType === 1 && (node.matches?.(selector) || node.querySelector?.(selector))
        );
    }

    function reconcileATHRWiring() {
        if (!isATHRRuntimeActive()) return;
        if (athrWiringState.reconciling || !document.body) return;
        athrWiringState.reconciling = true;
        const previousCurrency = activeGameCurrency;
        const previousDisplay = `${getDisplayAmountMode()}:${getLocalCurrencyCode()}`;
        try {
            removeLegacyWalletPopovers();
            filterUnsupportedStakeCurrencies(document);
            const displayChanged = syncDisplayModeFromStakeWalletSettings(document);
            syncActiveGameCurrencyFromDOM();
            updateStakeWalletBalances(document);
            normalizeATHRNativeCryptoZero(document);
            syncGameCurrencyAdornments();
            reconcilePayoutResults(document);

            const realInput = document.querySelector(INPUT_SELECTOR);
            const fakeInput = document.querySelector(FAKE_INPUT_SELECTOR);
            if (realInput && !fakeInput) {
                const wrapper = realInput.closest(WRAPPER_SELECTOR);
                if (wrapper) applyExactOverlayClone(wrapper, realInput);
            }

            if (settings.enableFakeBalance) updateLTCButtonBalance();
            const nextDisplay = `${getDisplayAmountMode()}:${getLocalCurrencyCode()}`;
            if (!displayChanged && (previousCurrency !== activeGameCurrency || previousDisplay !== nextDisplay)) {
                updateBalanceUI();
            }
        } catch (error) {
            console.warn('[ATHR WIRING] Reconcile skipped safely:', error);
        } finally {
            athrWiringState.reasons.clear();
            athrWiringState.reconciling = false;
        }
    }

    function paintATHRHeaderCurrencyIcon(button, currency) {
        const code = ensureCurrencyRegistered(currency);
        if (!button || !code) return false;
        const icon = Array.from(button.querySelectorAll('svg[data-ds-icon]')).find(svg =>
            ensureCurrencyRegistered(svg.getAttribute('data-athr-icon-rendered'))
            || ensureCurrencyRegistered(svg.getAttribute('data-ds-icon'))
            || ensureCurrencyRegistered(svg.closest?.('span[title]')?.getAttribute('title'))
        );
        if (!icon) return false;

        applyCurrencyIcon(icon, code);
        const titleHost = icon.closest?.('span[title]');
        if (titleHost) {
            titleHost.setAttribute('title', code.toLowerCase());
            titleHost.setAttribute('aria-label', `${CRYPTO_CURRENCIES[code].name} (${code})`);
        }
        return true;
    }

    function renderATHRCurrencySelectionImmediately(code, nativeChoice = null) {
        const currency = ensureCurrencyRegistered(code);
        if (!currency) return;

        currentBalance = getCryptoBalance(currency);
        const headerButton = document.querySelector(
            '#navigation-container-header button[data-testid="coin-toggle"], [data-testid="balance-toggle"] button[data-testid="coin-toggle"], button[data-testid="coin-toggle"]'
        ) || getActiveCurrencyButton();
        if (headerButton) {
            headerButton.setAttribute('data-athr-active-currency', currency);
            headerButton.setAttribute('data-athr-native-currency', currency);
            paintATHRHeaderCurrencyIcon(headerButton, currency);
            updateCurrencyButtonBalanceText(headerButton, currency);
        }
        if (nativeChoice) updateStakeWalletRowBalanceText(nativeChoice, currency);

        const fakeInput = document.querySelector(FAKE_INPUT_SELECTOR);
        const fakeWrapper = fakeInput?.closest?.('[data-tm-fake-wrapper="1"], .input-wrap');
        if (fakeWrapper) updateMoneyWrapperAdornment(fakeWrapper, currency);
        syncGameCurrencyAdornments();
        updateCurrencyConversion();
        refreshCurrencyControls();
        syncATHRHeaderCryptoTooltips(document, currency);
        normalizeATHRNativeCryptoZero(document);
    }

    function handleATHRWiringEvent(event) {
        const target = event.target?.nodeType === 1 ? event.target : event.target?.parentElement;
        if (!target || target.closest?.('#balance-ui')) return;
        const action = target.closest?.('button, [role="button"], [role="option"], label, [role="radio"], [role="switch"], input');
        if (!action) return;

        const nativeChoice = action.closest?.('button, [role="button"], [role="option"]');
        if (nativeChoice && isNativeCurrencyChoice(nativeChoice)) {
            const code = getNativeCurrencyFromToggleButton(nativeChoice);
            if (code) {
                if (activeBetSession && code !== activeBetSession.currency) {
                    event.preventDefault();
                    event.stopImmediatePropagation();
                    refreshBetSessionUI();
                    return;
                }
                stakeCurrencySyncToken += 1;
                manualActiveCurrency = null;
                athrWiringState.pendingTrustedCurrency = code;
                athrWiringState.pendingTrustedAt = Date.now();
                athrWiringState.candidateCurrency = code;
                athrWiringState.candidateCount = 2;
                athrWiringState.lastConfirmedCurrency = code;
                // Hold the trusted clicked coin during Stake's short Svelte
                // rerender, then paint its saved ATHR balance in the same tick.
                // This removes the old ~1 second stale header/tooltip value.
                setActiveGameCurrency(code, {
                    manual: false,
                    transient: true,
                    syncStake: false,
                    update: false,
                    conversion: false
                });
                renderATHRCurrencySelectionImmediately(code, nativeChoice);
                updateBalanceUI();
                requestAnimationFrame(() => {
                    if (document.activeElement === nativeChoice) nativeChoice.blur();
                });
                [0, 16, 80, 180].forEach(delay => {
                    setTimeout(() => scheduleATHRWiringSync('native-currency-choice', 0), delay);
                });
                return;
            }
        }

        const dialog = action.closest?.('[role="dialog"], [data-testid*="modal"], [data-modal-card="true"]');
        const actionText = `${action.getAttribute?.('data-testid') || ''} ${action.getAttribute?.('aria-label') || ''} ${action.textContent || ''}`;
        if (dialog || /wallet|settings|fiat|currency|display\s+crypto/i.test(actionText)) {
            const clickedFiatCode = dialog ? getFiatCodeFromControl(action) : null;
            if (clickedFiatCode && Object.prototype.hasOwnProperty.call(FIAT_COUNTRY_CODES, clickedFiatCode)) {
                pendingStakeFiatCode = clickedFiatCode;
            }
            // A change/input event fires after Stake has committed the radio or
            // switch state. Read it synchronously while the modal still exists;
            // the delayed observer remains as a rerender safety net.
            if (event.type === 'change' || event.type === 'input') {
                const displayChanged = syncDisplayModeFromStakeWalletSettings(document);
                if (displayChanged && settings.enableFakeBalance) updateBalanceUI();
            }
            scheduleATHRWiringSync('wallet-settings-event', 220);
        }
    }

    function installStakeWalletSettingsObserver() {
        if (athrWiringState.installed || !document.documentElement) return;
        athrWiringState.installed = true;
        document.addEventListener('pointerdown', handleATHRWiringEvent, true);
        document.addEventListener('click', handleATHRWiringEvent, true);
        document.addEventListener('change', handleATHRWiringEvent, true);
        document.addEventListener('input', handleATHRWiringEvent, true);
        stakeWalletDisplayObserver = new MutationObserver(mutations => {
            if (mutations.some(isATHRWiringMutationRelevant)) scheduleATHRWiringSync('dom-mutation', 120);
        });
        athrWiringState.observer = stakeWalletDisplayObserver;
        stakeWalletDisplayObserver.observe(document.documentElement, {
            childList: true,
            subtree: true,
            characterData: true,
            attributes: true,
            attributeFilter: ['checked', 'aria-checked', 'aria-selected', 'aria-pressed', 'data-checked', 'data-state', 'data-testid', 'data-currency', 'data-currency-code', 'value', 'placeholder', 'disabled']
        });
        scheduleATHRWiringSync('install', 240);
    }

    // Keep Stake's own money-field structure. ATHR only updates the existing
    // native adornment; it never inserts a second fiat prefix or a hand-built
    // flag. This prevents the detached "$" shown beside the bet input.

    function updateMoneyWrapperAdornment(wrapper, currency = activeGameCurrency) {
        if (!wrapper || wrapper.closest?.('#balance-ui, #athr-wallet-balances-popover')) return;
        const content = wrapper.querySelector('.input-content') || wrapper;
        const input = content.querySelector('input');
        if (!input) return;

        // Remove prefixes created by v4.9 before doing anything else. Native
        // Stake prefixes already exist in the cloned wrapper when fiat is used.
        content.querySelectorAll('[data-athr-display-prefix="true"], .athr-display-prefix')
            .forEach(element => element.remove());

        const directAfterIcons = Array.from(content.children).filter(element => element.classList?.contains('after-icon'));
        let afterIcon = directAfterIcons[0] || null;
        directAfterIcons.slice(1).forEach(element => element.remove());
        const cryptoMode = getDisplayAmountMode() === 'CRYPTO';
        if (cryptoMode) {
            if (!afterIcon) {
                afterIcon = document.createElement('div');
                afterIcon.className = 'after-icon athr-generated-after-icon';
                content.insertBefore(afterIcon, input);
            } else if (!afterIcon.hasAttribute('data-athr-native-html')) {
                afterIcon.setAttribute('data-athr-native-html', afterIcon.innerHTML);
            }
            afterIcon.innerHTML = getCurrencyIconSVG(currency, 20, 'athr-input-currency-icon');
            afterIcon.setAttribute('data-athr-display-adornment', normalizeCurrency(currency));
            afterIcon.setAttribute('data-athr-icon-owner', 'bet-adornment');
        } else {
            // The hidden original input remains mounted and receives Stake's
            // actual USD/INR/etc. flag changes. Mirror that exact native node.
            const nativeWrapper = wrapper.matches?.('[data-tm-fake-wrapper="1"]')
                ? wrapper.nextElementSibling?.matches?.('[data-tm-exact-overlay-applied="1"]')
                    ? wrapper.nextElementSibling
                    : null
                : null;
            const nativeAfterIcon = nativeWrapper?.querySelector?.('.after-icon');
            if (nativeAfterIcon) {
                const clone = nativeAfterIcon.cloneNode(true);
                clone.removeAttribute('data-athr-display-adornment');
                clone.removeAttribute('data-athr-icon-owner');
                if (afterIcon) afterIcon.replaceWith(clone);
                else content.insertBefore(clone, input);
            } else if (afterIcon?.hasAttribute('data-athr-native-html')) {
                afterIcon.innerHTML = afterIcon.getAttribute('data-athr-native-html') || '';
                afterIcon.removeAttribute('data-athr-native-html');
                afterIcon.removeAttribute('data-athr-display-adornment');
            } else if (afterIcon?.classList.contains('athr-generated-after-icon')) {
                afterIcon.remove();
            }
        }

        // A fiat token must never remain visible when Stake is in native crypto
        // mode. Do not create one in fiat mode; Stake owns that rendering.
        Array.from(content.children).forEach(element => {
            if (element === input || element.classList?.contains('after-icon')) return;
            if (element.querySelector?.('input, svg')) return;
            const text = String(element.textContent || '').trim();
            const isFiatToken = text === '$' || text === getLocalCurrencySymbol() || text === getLocalCurrencyCode();
            if (!isFiatToken) return;
            element.hidden = cryptoMode;
            element.toggleAttribute('data-athr-native-fiat-prefix', true);
        });
        wrapper.setAttribute('data-athr-display-mode', getDisplayAmountMode());
        wrapper.setAttribute('data-athr-display-currency', getStakeDisplayCurrencyCode(currency));
    }

    function syncGameCurrencyAdornments() {
        const fakeInput = document.querySelector(FAKE_INPUT_SELECTOR);
        const currency = activeBetSession ? getBetSessionCurrency() : activeGameCurrency;
        const wrappers = new Set([
            fakeInput?.closest?.('[data-tm-fake-wrapper="1"], .input-wrap'),
            ...getStakeProfitInputs().map(input => input.closest?.('.input-wrap'))
        ].filter(Boolean));
        wrappers.forEach(wrapper => updateMoneyWrapperAdornment(wrapper, currency));
    }

    // v5.4.2: Stake can mount more than one game sidebar during responsive
    // transitions. Update every matching native profit control, with the stable
    // data-testid first and the supplied Svelte path only as a deployment fallback.
    function getStakeProfitInputs(root = document) {
        if (!root?.querySelectorAll) return [];
        const inputs = new Set();
        const addMatches = selector => {
            try {
                if (root.nodeType === 1 && root.matches?.(selector)) inputs.add(root);
                root.querySelectorAll(selector).forEach(input => inputs.add(input));
            } catch (error) { }
        };

        addMatches(PROFIT_INPUT_PRIMARY_SELECTOR);
        addMatches(PROFIT_INPUT_EXACT_FALLBACK_SELECTOR);
        addMatches('input[readonly].input.spacing-expanded[type="text"], input[readonly][autocomplete="on"].input.spacing-expanded');

        return Array.from(inputs).filter(input => {
            if (!(input instanceof HTMLInputElement) || input.closest?.('#balance-ui')) return false;
            if (input.matches(PROFIT_INPUT_PRIMARY_SELECTOR)) return true;
            const label = input.closest?.('label');
            const context = `${label?.textContent || ''} ${label?.className || ''} ${input.closest?.('.profit')?.className || ''}`;
            return /total\s+profit|\bprofit\b/i.test(context);
        }).sort((a, b) => Number(isATHRNativeMirrorVisible(b)) - Number(isATHRNativeMirrorVisible(a)));
    }

    function getStakeProfitLabel(input) {
        return input?.closest?.('label') || input?.closest?.('.profit') || null;
    }

    function setStakeReadonlyInputValue(input, nextValue) {
        if (!input) return false;
        const value = String(nextValue ?? '');
        const changed = input.value !== value || input.getAttribute('value') !== value;
        if (!changed) return false;

        const descriptor = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value');
        if (descriptor?.set) descriptor.set.call(input, value);
        else input.value = value;
        if (input.getAttribute('value') !== value) input.setAttribute('value', value);
        input.setAttribute('data-athr-profit-rendered', 'true');
        return true;
    }

    let athrNativeMirrorObserver = null;
    let athrNativeMirrorTimer = 0;
    let athrNativeMirrorInterval = 0;
    const athrLiveProfitState = {
        active: false,
        amountUsd: 0,
        currency: DEFAULT_CURRENCY,
        multiplier: '1.00'
    };

    function isATHRNativeMirrorVisible(element) {
        if (!element || !element.isConnected) return false;
        const style = window.getComputedStyle?.(element);
        if (style && (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity) === 0)) return false;
        const rect = element.getBoundingClientRect?.();
        return !!rect && rect.width > 0 && rect.height > 0;
    }

    function compactATHRNativeNumber(rawValue) {
        const raw = String(rawValue ?? '').trim();
        if (!raw) return '';
        if (!/^[+-]?[\d,]+(?:\.\d+)?$/u.test(raw)) return raw;
        return raw.replace(/(\.\d*?[1-9])0+$/u, '$1').replace(/\.0+$/u, '');
    }

    function getStakeNativeProfitSnapshot() {
        const input = getStakeProfitInputs()[0] || null;
        if (!input) return null;

        const label = getStakeProfitLabel(input);
        const conversion = label?.querySelector('div[data-testid="conversion-amount"] span[data-ds-text="true"]') || null;
        const multiplierLabel = label?.querySelector('span[slot="label"][data-ds-text="true"]') || null;
        const currency = activeBetSession ? getBetSessionCurrency() : activeGameCurrency;
        const value = compactATHRNativeNumber(input.value);
        const conversionText = String(conversion?.textContent || '').replace(/\s+/g, ' ').trim();
        const unit = getBalanceInputUnitLabel(currency);
        return {
            value,
            conversionText,
            multiplierText: String(multiplierLabel?.textContent || 'Total Profit').replace(/\s+/g, ' ').trim(),
            unit,
            source: input.hasAttribute('data-testid') ? 'profit-input' : 'profit-fallback'
        };
    }

    function getStakeNativeWalletDisplaySnapshot() {
        const roots = Array.from(document.querySelectorAll('#svelte > div.fixed.left-0, div.fixed.left-0'))
            .filter(root => root && !root.closest?.('#balance-ui'));
        let best = null;

        for (const root of roots) {
            const candidates = Array.from(root.querySelectorAll('span[data-ds-text="true"]'));
            for (const span of candidates) {
                if (span.closest('[data-athr-wallet-overview-section], [data-athr-wallet-list]') || !isATHRNativeMirrorVisible(span)) continue;
                const text = String(span.textContent || '').replace(/\s+/g, ' ').trim();
                if (!text || text.length > 40 || !/[-+]?[$\u20B9\u20AC\u00A3\u00A5]?\s*\d[\d,.]*/u.test(text)) continue;

                const classText = String(span.className || '');
                let score = 0;
                if (classText.includes('edge-typography-body-md-strong')) score += 30;
                if (classText.includes('typography-display-sm')) score += 45;
                if (/[$\u20B9\u20AC\u00A3\u00A5]/u.test(text)) score += 24;
                if (/\b[A-Z]{2,6}\b/u.test(text)) score += 14;
                if (span.closest('.inline-flex.items-center')) score += 12;
                if (span.closest('.fixed.left-0')) score += 8;

                if (!best || score > best.score) best = { text, score, source: 'wallet-overlay' };
            }
        }
        return best;
    }

    function getStakeWalletOverviewBalanceTargets(root = document) {
        if (!root?.querySelectorAll) return [];
        const overlayRoots = new Set(getATHRWalletOverviewSurfaces(root));
        const ranked = [];

        overlayRoots.forEach(overlay => {
            if (overlay.closest?.('#balance-ui')) return;
            Array.from(overlay.querySelectorAll('span[data-ds-text="true"]')).forEach(span => {
                if (span.closest('[data-athr-wallet-overview-section], [data-athr-wallet-list], button, [role="button"], [role="option"], [role="menu"], [role="listbox"]')) return;
                if (span.children.length > 0) return;
                const text = String(span.textContent || '').replace(/\s+/g, ' ').trim();
                if (!text || text.length > 40 || !/[-+]?[$\u20B9\u20AC\u00A3\u00A5]?\s*\d[\d,.]*/u.test(text)) return;

                const classText = String(span.className || '');
                const nearbyText = String(span.closest('.inline-flex.items-center')?.parentElement?.textContent || '');
                let score = 0;
                if (span.hasAttribute('data-athr-wallet-overview-balance')) score += 200;
                if (classText.includes('edge-typography-body-md-strong')) score += 85;
                if (classText.includes('edge-typography-display-sm') || classText.includes('typography-display-sm')) score += 95;
                if (classText.includes('text-neutral-default')) score += 20;
                if (span.closest('span.content')) score += 20;
                if (span.closest('.inline-flex.items-center')) score += 25;
                if (/[$\u20B9\u20AC\u00A3\u00A5]/u.test(text)) score += 20;
                if (/\bbalance\b/i.test(nearbyText) || /\bbalance\b/i.test(overlay.textContent || '')) score += 20;
                ranked.push({ element: span, score });
            });
        });

        ranked.sort((a, b) => b.score - a.score);
        if (!ranked.length || ranked[0].score < 80) return [];
        const bestScore = ranked[0].score;
        return ranked.filter(item => item.score >= bestScore - 5).map(item => item.element);
    }

    function updateStakeWalletOverviewBalance(root = document) {
        if (!settings.enableFakeBalance) return 0;
        const totalUsd = SUPPORTED_CURRENCY_CODES.reduce((sum, code) => sum + Math.max(0, Number(getCryptoBalance(code)) || 0), 0);
        const formatted = getATHRWalletSecondaryValue(totalUsd, selectedBalanceCurrency);
        const targets = getStakeWalletOverviewBalanceTargets(root);
        targets.forEach(span => {
            if (span.textContent !== formatted) span.textContent = formatted;
            span.setAttribute('data-athr-wallet-overview-balance', 'TOTAL');
            span.setAttribute('data-athr-balance-rendered', 'TOTAL');
        });
        return targets.length;
    }

    function formatStakeProfitConversion(amountUsd, currency) {
        const code = ensureCurrencyRegistered(currency) || getBetSessionCurrency();
        if (getDisplayAmountMode() === 'CRYPTO') return formatNativeFiatConversion(amountUsd);
        return `${formatCryptoDisplayAmount(amountUsd, code)} ${code}`;
    }

    function syncStakeNativeProfitDisplay() {
        if (!athrLiveProfitState.active) return 0;
        const code = ensureCurrencyRegistered(athrLiveProfitState.currency) || getBetSessionCurrency();
        const amountUsd = Number(athrLiveProfitState.amountUsd) || 0;
        const displayValue = formatDisplayInputNumber(usdToDisplayInputValue(amountUsd, code), code);
        let updated = 0;

        getStakeProfitInputs().forEach(input => {
            const label = getStakeProfitLabel(input);
            if (setStakeReadonlyInputValue(input, displayValue)) updated += 1;
            updateMoneyWrapperAdornment(input.closest?.('.input-wrap'), code);

            const conversion = label?.querySelector?.('div[data-testid="conversion-amount"] span[data-ds-text="true"]');
            const conversionText = formatStakeProfitConversion(amountUsd, code);
            if (conversion && conversion.textContent !== conversionText) conversion.textContent = conversionText;

            const multiplierLabel = label?.querySelector?.('span[slot="label"][data-ds-text="true"]');
            const multiplierText = `Total Profit (${athrLiveProfitState.multiplier}\u00D7)`;
            if (multiplierLabel && multiplierLabel.textContent !== multiplierText) multiplierLabel.textContent = multiplierText;
        });
        normalizeATHRNativeCryptoZero(document);
        return updated;
    }

    function syncATHRNativeReadOnlyMetrics() {
        syncStakeNativeProfitDisplay();
        syncATHRNativeWalletOverview(document);
        updateStakeWalletOverviewBalance(document);
        normalizeATHRNativeCryptoZero(document);
        const panel = document.getElementById('balance-ui');
        if (!panel) return;

        const profitValue = document.getElementById('athr-native-profit-live');
        const profitMeta = document.getElementById('athr-native-profit-meta');
        const walletValue = document.getElementById('athr-native-wallet-live');
        const walletMeta = document.getElementById('athr-native-wallet-meta');

        const profit = getStakeNativeProfitSnapshot();
        if (profitValue) {
            const main = profit?.value ? `${profit.value}${profit.unit ? ` ${profit.unit}` : ''}` : 'Waiting for game';
            if (profitValue.textContent !== main) profitValue.textContent = main;
            profitValue.classList.toggle('is-live', !!profit?.value);
        }
        if (profitMeta) {
            profitMeta.textContent = profit
                ? [profit.multiplierText, profit.conversionText].filter(Boolean).join(' \u00B7 ') || 'Native Stake profit input'
                : 'input[data-testid="profit-input"] not mounted';
        }

        const wallet = getStakeNativeWalletDisplaySnapshot();
        if (walletValue) {
            walletValue.textContent = wallet?.text || 'Wallet panel closed';
            walletValue.classList.toggle('is-live', !!wallet?.text);
        }
        if (walletMeta) {
            walletMeta.textContent = wallet?.text
                ? 'Live synchronized with Stake wallet surface'
                : 'Open the Stake wallet surface to synchronize its visible value';
        }
    }

    function scheduleATHRNativeReadOnlyMetrics(delay = 60) {
        // Coalesce updates without postponing them during continuous animation.
        if (athrNativeMirrorTimer) return;
        athrNativeMirrorTimer = setTimeout(() => {
            athrNativeMirrorTimer = 0;
            syncATHRNativeReadOnlyMetrics();
        }, Math.max(0, Number(delay) || 0));
    }

    function installATHRNativeReadOnlyMirror() {
        if (!document.documentElement) return;
        if (!athrNativeMirrorObserver) {
            const eventSync = () => scheduleATHRNativeReadOnlyMetrics(0);
            document.addEventListener('input', eventSync, true);
            document.addEventListener('change', eventSync, true);
            document.addEventListener('click', () => scheduleATHRNativeReadOnlyMetrics(90), true);

            athrNativeMirrorObserver = new MutationObserver(mutations => {
                const relevant = mutations.some(mutation => {
                    const target = mutation.target?.nodeType === 1 ? mutation.target : mutation.target?.parentElement;
                    return !!target && !target.closest?.('#balance-ui, [data-athr-wallet-list], [data-athr-wallet-overview-section], [data-athr-balance-rendered]');
                });
                if (relevant) scheduleATHRNativeReadOnlyMetrics(80);
            });
            athrNativeMirrorObserver.observe(document.documentElement, {
                childList: true,
                subtree: true,
                characterData: true,
                attributes: true,
                attributeFilter: ['value', 'data-testid', 'class', 'style', 'aria-hidden']
            });
        }
        if (!athrNativeMirrorInterval) {
            // Property changes such as input.value do not always emit DOM
            // mutations, so use a low-frequency idempotent refresh as a safety net.
            athrNativeMirrorInterval = setInterval(syncATHRNativeReadOnlyMetrics, 700);
        }
        scheduleATHRNativeReadOnlyMetrics(0);
    }

    // Native Stake wallet tooltip only. Remove any leftover v4.9 nodes and do
    // not intercept trusted header clicks; Stake owns opening, focus, search,
    // keyboard handling and dismissal on mobile.
    function removeLegacyWalletPopovers() {
        document.querySelectorAll?.('#athr-wallet-balances-popover, .athr-wallet-balances-popover, #athr-all-balances-tooltip, .athr-all-balances-tooltip, [data-athr-tooltip="true"], [data-athr-stale-tooltip="true"]')
            .forEach(element => element.remove());
        document.body?.classList.remove('athr-header-wallet-open');
    }

    function refreshHeaderWalletPanel() {
        removeLegacyWalletPopovers();
    }

    function installHeaderWalletPanel() {
        removeLegacyWalletPopovers();
    }

    // Save all independent ATHR wallet balances while keeping the old single-
    // balance key for backward compatibility with existing installs.
    function saveBalance() {
        cryptoBalances[activeGameCurrency] = Math.max(0, Number(currentBalance) || 0);
        if (settings.saveBalance) {
            localStorage.setItem(CRYPTO_BALANCES_KEY, JSON.stringify(cryptoBalances));
            localStorage.setItem(STORAGE_KEY, getCryptoBalance(DEFAULT_CURRENCY).toString());
        } else {
            localStorage.removeItem(STORAGE_KEY);
            localStorage.removeItem(CRYPTO_BALANCES_KEY);
        }
    }

