    // Helper functions for color manipulation
    function hexToRgba(hex, alpha = 1) {
        const r = parseInt(hex.slice(1, 3), 16);
        const g = parseInt(hex.slice(3, 5), 16);
        const b = parseInt(hex.slice(5, 7), 16);
        return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    }

    function adjustColor(hex, amount, alpha = 1) {
        const r = Math.max(0, Math.min(255, parseInt(hex.slice(1, 3), 16) + amount));
        const g = Math.max(0, Math.min(255, parseInt(hex.slice(3, 5), 16) + amount));
        const b = Math.max(0, Math.min(255, parseInt(hex.slice(5, 7), 16) + amount));
        if (alpha < 1) {
            return `rgba(${r}, ${g}, ${b}, ${alpha})`;
        }
        return `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`;
    }

    function blockNoRoundPlayedNotification() {
        // Function to check and remove unwanted notifications
        const checkAndRemoveNotification = (notification) => {
            if (!notification) return false;

            // Check notification content
            const notificationBody = notification.querySelector('.notification-body');
            if (notificationBody) {
                const textContent = notificationBody.textContent || '';

                // Block "No round played" notification
                if (textContent.includes('No round played')) {
                    notification.remove();
                    console.log('[NOTIFICATION BLOCKER] Removed "No round played" notification');
                    return true;
                }

                // Block "Please slow down" notification
                if (textContent.includes('Please slow down')) {
                    notification.style.display = 'none';
                    notification.remove();
                    console.log('[NOTIFICATION BLOCKER] Removed "Please slow down" notification');
                    return true;
                }

                // Block "Bet cannot be found or is unavailable" notification
                if (textContent.includes('Bet cannot be found or is unavailable')) {
                    notification.style.display = 'none';
                    notification.remove();
                    console.log('[NOTIFICATION BLOCKER] Removed "Bet cannot be found" notification');
                    return true;
                }
            }
            return false;
        };

        // Function to check all notifications on the page
        const checkAllNotifications = () => {
            const allNotifications = document.querySelectorAll('[data-testid="notification"]');
            allNotifications.forEach(notification => {
                checkAndRemoveNotification(notification);
            });
        };

        // Check existing notifications immediately
        checkAllNotifications();

        // Watch for new notifications using MutationObserver
        const observer = new MutationObserver((mutations) => {
            mutations.forEach((mutation) => {
                mutation.addedNodes.forEach((node) => {
                    if (node.nodeType === 1) { // Element node
                        // Check if the added node is a notification
                        if (node.matches && node.matches('[data-testid="notification"]')) {
                            checkAndRemoveNotification(node);
                        }
                        // Also check for notifications inside the added node
                        const notifications = node.querySelectorAll ? node.querySelectorAll('[data-testid="notification"]') : [];
                        notifications.forEach(notification => {
                            checkAndRemoveNotification(notification);
                        });
                    }
                });
            });
        });

        // Start observing the document body for new notifications
        observer.observe(document.body, {
            childList: true,
            subtree: true
        });

        // Periodic backup check every 500ms to catch any missed notifications
        setInterval(checkAllNotifications, 1500);

        console.log('[NOTIFICATION BLOCKER] Active - blocking unwanted notifications');
    }

